package com.bahealerorder.defender;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class DefenderInventoryTest
{
	@Test
	public void detectsRegularAndImcandoHammer()
	{
		assertTrue(DefenderInventory.isHammer(ItemID.HAMMER, "Hammer"));
		assertTrue(DefenderInventory.isHammer(12345, "Imcando hammer"));
		assertTrue(DefenderInventory.isImcandoHammer(ItemID.IMCANDO_HAMMER, null));
		assertTrue(DefenderInventory.isImcandoHammer(ItemID.IMCANDO_HAMMER_OFFHAND, null));
		assertFalse(DefenderInventory.isHammer(ItemID.LOGS, "Logs"));
	}
}

package com.bahealerorder.healer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.bahealerorder.healer.codes.HealerCodeExport;
import com.bahealerorder.healer.codes.HealerCodeExportType;
import com.bahealerorder.healer.codes.HealerCodeDefaultRole;
import com.bahealerorder.healer.codes.HealerCodeParser;
import com.bahealerorder.healer.codes.HealerCodeStoreNormalizer;
import com.bahealerorder.healer.codes.RunPreset;
import com.bahealerorder.healer.codes.StrategyStore;
import com.bahealerorder.healer.codes.WaveCode;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class HealerCodeManagerTest
{
	@Test
	public void importsRunPresetWithoutReplacingDifferentSameNameWaveCode()
	{
		StrategyStore store = new StrategyStore();
		WaveCode existing = HealerCodeParser.parseWaveCode("user:wave:fast-five", "Fast Five", 5, false, "1-1-1");
		store.getWaveCodes().add(existing);
		Map<Integer, String> existingWaveCodeIds = new HashMap<>();
		existingWaveCodeIds.put(5, existing.getId());
		store.getRunPresets().add(new RunPreset("user:preset:main-run", "Main Run", false, existingWaveCodeIds));

		HealerCodeManager manager = new HealerCodeManager(store, new Gson());
		WaveCode importedCode = HealerCodeParser.parseWaveCode("import:wave:fast-five", "Fast Five", 5, false, "2-2-2");
		Map<Integer, String> importedWaveCodeIds = new HashMap<>();
		importedWaveCodeIds.put(5, importedCode.getId());
		RunPreset importedPreset = new RunPreset(null, "Main Run", false, importedWaveCodeIds);
		String json = new Gson().toJson(new HealerCodeExport(
				2,
				HealerCodeExportType.RUN_PRESET,
				importedPreset,
				null,
				Collections.singletonList(importedCode)
		));

		assertEquals(true, manager.importRunPresetJson(json));

		WaveCode imported = manager.getActiveWaveCode(5);
		assertNotNull(imported);
		assertEquals("Fast Five", imported.getName());
		assertEquals(2, imported.getCall(0).getInstruction(1).getTargetFoodCount());
		assertEquals("1-1-1", existing.getSourceText());
		assertEquals(imported.getId(), manager.getActiveWaveCodeId(5));
		assertEquals(2, store.getWaveCodes().size());
		assertEquals(2, store.getRunPresets().size());
	}

	@Test
	public void importsSameNameSameContentWaveCodeAsExistingCode()
	{
		StrategyStore store = new StrategyStore();
		WaveCode existing = HealerCodeParser.parseWaveCode("user:wave:fast-five", "Fast Five", 5, false, "1-1-1");
		store.getWaveCodes().add(existing);

		HealerCodeManager manager = new HealerCodeManager(store, new Gson());
		WaveCode importedCode = HealerCodeParser.parseWaveCode("import:wave:fast-five", "Fast Five", 5, false, "1-1-1");
		String json = new Gson().toJson(new HealerCodeExport(
				2,
				HealerCodeExportType.WAVE_CODE,
				null,
				importedCode,
				null
		));

		assertNotNull(manager.importHealerCodeJson(json, 5));

		assertEquals(existing.getId(), manager.getActiveWaveCodeId(5));
		assertEquals(1, store.getWaveCodes().size());
	}

	@Test
	public void clearingWaveCodeSelectionDoesNotFallBackToActivePreset()
	{
		StrategyStore store = new StrategyStore();
		WaveCode waveOne = HealerCodeParser.parseWaveCode("user:wave:one", "Wave One", 1, false, "1-1-1");
		WaveCode waveTwo = HealerCodeParser.parseWaveCode("user:wave:two", "Wave Two", 2, false, "2-2-2");
		store.getWaveCodes().add(waveOne);
		store.getWaveCodes().add(waveTwo);

		Map<Integer, String> waveCodeIds = new HashMap<>();
		waveCodeIds.put(1, waveOne.getId());
		waveCodeIds.put(2, waveTwo.getId());
		store.getRunPresets().add(new RunPreset("user:preset:main-run", "Main Run", false, waveCodeIds));

		HealerCodeManager manager = new HealerCodeManager(store, new Gson());

		manager.applyRunPreset("user:preset:main-run");
		manager.setActiveWaveCodeId(1, null);

		assertNull(manager.getActiveWaveCode(1));
		assertEquals(waveTwo.getId(), manager.getActiveWaveCodeId(2));
		assertEquals(waveTwo, manager.getActiveWaveCode(2));
		assertNull(manager.getActiveRunPresetId());
	}

	@Test
	public void exportsAndImportsUnnamedCurrentPresetAsSelections()
	{
		StrategyStore store = new StrategyStore();
		WaveCode waveOne = HealerCodeParser.parseWaveCode("user:wave:one", "Wave One", 1, false, "1-1-1");
		store.getWaveCodes().add(waveOne);
		store.getActiveWaveCodeIds().put(1, waveOne.getId());

		HealerCodeManager manager = new HealerCodeManager(store, new Gson());
		String json = manager.exportCurrentRunPreset(null).getJson();
		HealerCodeExport exported = new Gson().fromJson(json, HealerCodeExport.class);

		assertEquals(waveOne.getId(), exported.getPreset().getWaveCodeId(1));
		assertEquals(waveOne.getId(), exported.getWaveCodes().get(0).getId());

		StrategyStore importedStore = new StrategyStore();
		HealerCodeManager importedManager = new HealerCodeManager(importedStore, new Gson());

		assertEquals(true, importedManager.importRunPresetJson(json));
		assertNull(importedManager.getActiveRunPresetId());
		assertNotNull(importedManager.getActiveWaveCode(1));
		assertEquals(0, importedStore.getRunPresets().size());
		assertEquals("Wave One", importedManager.getActiveWaveCode(1).getName());
	}

	@Test
	public void savingPresetWithBuiltInNameCreatesUserCopy()
	{
		StrategyStore store = new StrategyStore();
		HealerCodeManager manager = new HealerCodeManager(store, new Gson());
		RunPreset builtInPreset = firstBuiltInPreset(manager);
		assertNotNull(builtInPreset);
		manager.applyRunPreset(builtInPreset.getId());

		RunPreset saved = manager.createUserPresetFromActive(builtInPreset.getName());

		assertNotNull(saved);
		assertEquals(false, saved.isBuiltIn());
		assertEquals(false, builtInPreset.getId().equals(saved.getId()));
		assertEquals(1, store.getRunPresets().size());
		assertEquals(saved.getId(), manager.getActiveRunPresetId());
	}

	@Test
	public void applyDefaultRunPresetReportsOnlyActualPresetChanges()
	{
		StrategyStore store = new StrategyStore();
		WaveCode waveOne = HealerCodeParser.parseWaveCode("user:wave:one", "Wave One", 1, false, "1-1-1");
		store.getWaveCodes().add(waveOne);
		Map<Integer, String> waveCodeIds = new HashMap<>();
		waveCodeIds.put(1, waveOne.getId());
		RunPreset preset = new RunPreset("user:preset:solo", "Solo", false, waveCodeIds);
		store.getRunPresets().add(preset);
		store.getActiveWaveCodeIds().putAll(waveCodeIds);

		HealerCodeManager manager = new HealerCodeManager(store, new Gson());
		assertEquals(true, manager.setDefaultRunPresetId(HealerCodeDefaultRole.SOLO_HEALER, preset.getId()));

		assertEquals(preset, manager.applyDefaultRunPreset(HealerCodeDefaultRole.SOLO_HEALER));
		assertEquals(preset.getId(), manager.getActiveRunPresetId());
		assertNull(manager.applyDefaultRunPreset(HealerCodeDefaultRole.SOLO_HEALER));
	}

	@Test
	public void builtInWaveCodeNamesOmitExpectedWaveEnd()
	{
		HealerCodeManager manager = new HealerCodeManager(new StrategyStore(), new Gson());
		WaveCode builtIn = manager.findBuiltInWaveCode("builtin:w4:regular");

		assertNotNull(builtIn);
		assertEquals("Reg", builtIn.getName());
		assertEquals("Reg (42)", HealerCodeManager.waveCodeDisplayName(builtIn));
	}

	@Test
	public void savingBuiltInWaveCodeCreatesResettableOverrideWithoutRenaming()
	{
		StrategyStore store = new StrategyStore();
		HealerCodeManager manager = new HealerCodeManager(store, new Gson());
		WaveCode builtIn = manager.findBuiltInWaveCode("builtin:w4:regular");
		WaveCode draft = HealerCodeParser.parseWaveCode(builtIn.getId(), builtIn.getName(), builtIn.getWave(), false, "9-9-9-9");

		WaveCode saved = manager.saveWaveCode(builtIn.getId(), draft);

		assertNotNull(saved);
		assertEquals(builtIn.getId(), saved.getId());
		assertEquals(builtIn.getName(), saved.getName());
		assertEquals(true, saved.isBuiltIn());
		assertEquals(true, manager.isModifiedBuiltInWaveCode(builtIn.getId()));
		assertEquals(1, store.getWaveCodes().size());
		assertEquals(9, manager.findWaveCode(builtIn.getId()).getCall(0).getInstruction(1).getTargetFoodCount());

		assertEquals(true, manager.resetBuiltInWaveCode(builtIn.getId()));
		assertEquals(false, manager.isModifiedBuiltInWaveCode(builtIn.getId()));
		assertEquals(0, store.getWaveCodes().size());
		assertEquals(2, manager.findWaveCode(builtIn.getId()).getCall(0).getInstruction(1).getTargetFoodCount());
	}

	@Test
	public void v1StoreNormalizeKeepsRunPresetsAndMergesStoredBuiltIns()
	{
		String json = "{"
				+ "\"activeRunPresetId\":\"user:preset:x69\","
				+ "\"activeWaveCodeIds\":{\"1\":\"user:wave:1-regular\",\"4\":\"builtin:w4:regular\"},"
				+ "\"runPresets\":[{\"id\":\"user:preset:x69\",\"name\":\"x69\",\"builtIn\":false,"
				+ "\"waveCodes\":{\"1\":\"user:wave:1-regular\",\"4\":\"builtin:w4:regular\"}}],"
				+ "\"waveCodes\":[{\"id\":\"user:wave:1-regular\",\"name\":\"Regular\",\"wave\":1,"
				+ "\"builtIn\":false,\"sourceText\":\"1-1\"},"
				+ "{\"id\":\"builtin:w4:regular\",\"name\":\"Regular\",\"wave\":4,"
				+ "\"builtIn\":true,\"sourceText\":\"2-4-2(27) //\\n0-0-0-8\"}]"
				+ "}";
		StrategyStore store = new Gson().fromJson(json, StrategyStore.class);

		assertEquals(true, HealerCodeStoreNormalizer.normalize(store, 2));

		assertEquals(2, store.getVersion());
		assertEquals("user:preset:x69", store.getActiveRunPresetId());
		assertEquals(1, store.getRunPresets().size());
		assertEquals("x69", store.getRunPresets().get(0).getName());
		assertEquals("user:wave:1-regular", store.getRunPresets().get(0).getWaveCodeId(1));
		assertEquals("builtin:w4:regular", store.getRunPresets().get(0).getWaveCodeId(4));
		assertEquals(2, store.getWaveCodes().size());
		assertEquals("1-1", store.getWaveCodes().get(0).getSourceText());

		HealerCodeManager manager = new HealerCodeManager(store, new Gson());
		int builtInCount = 0;
		for (WaveCode code : manager.getWaveCodesForWave(4))
		{
			if ("builtin:w4:regular".equals(code.getId()))
			{
				builtInCount++;
			}
		}
		assertEquals(1, builtInCount);
	}

	private static RunPreset firstBuiltInPreset(HealerCodeManager manager)
	{
		for (RunPreset preset : manager.getRunPresets())
		{
			if (preset.isBuiltIn())
			{
				return preset;
			}
		}
		return null;
	}
}

package com.bahealerorder.healer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.bahealerorder.common.BaHealerSyncMessage;
import com.bahealerorder.common.BaOverviewNpcType;
import com.bahealerorder.common.BaWaveOverviewSnapshot;
import com.bahealerorder.common.BaWaveOverviewState;
import org.junit.Test;

public class HealerSharedStateTest
{
	@Test
	public void observedDeathOverwritesEarlierPresumedDeath()
	{
		HealerSharedState state = new HealerSharedState();

		assertTrue(state.recordPresumedDeath(1, 204));
		assertEquals(204, state.getActualDeathTick(1).intValue());
		assertFalse(state.isObservedDeath(1));

		assertTrue(state.recordDeath(1, 207));
		assertEquals(207, state.getActualDeathTick(1).intValue());
		assertTrue(state.isObservedDeath(1));

		assertFalse(state.recordDeath(1, 208));
		assertEquals(207, state.getActualDeathTick(1).intValue());
	}

	@Test
	public void visibleAliveHealerClearsPresumedDeath()
	{
		HealerSharedState state = new HealerSharedState();

		assertTrue(state.recordPresumedDeath(1, 204));
		assertTrue(state.clearPresumedDeath(1));
		assertNull(state.getActualDeathTick(1));

		assertTrue(state.recordDeath(1, 207));
		assertEquals(207, state.getActualDeathTick(1).intValue());
	}

	@Test
	public void partyPredictionIsOnlyAppliedWhenAccepted()
	{
		HealerSharedState state = new HealerSharedState();
		BaHealerSyncMessage message = message(30, false, false);

		state.updateFromParty(message, false);
		assertNull(state.getPredictedDeathTick(1));

		state.updateFromParty(message, true);
		assertEquals(30, state.getPredictedDeathTick(1).intValue());
	}

	@Test
	public void healthRatioModeIsMonotonic()
	{
		HealerSharedState state = new HealerSharedState();

		state.updateFromParty(message(30, false, true), true);
		assertTrue(state.isHealthRatioMode(1));

		state.updateFromParty(message(31, false, false), true);
		assertTrue(state.isHealthRatioMode(1));
	}

	@Test
	public void overviewSnapshotIncludesHealerPredictionAndDeath()
	{
		HealerSharedState state = new HealerSharedState();
		state.startWave(1);
		state.recordLocalSpawn(1, 10, 0);
		state.recordPrediction(1, 30, false);

		BaWaveOverviewSnapshot predicted = BaWaveOverviewSnapshot.fromStates(1, new BaWaveOverviewState(), state);
		assertEquals(30, predicted.getPredictedDeathTick(BaOverviewNpcType.HEALER, 1).intValue());

		state.recordDeath(1, 31);
		BaWaveOverviewSnapshot dead = BaWaveOverviewSnapshot.fromStates(1, new BaWaveOverviewState(), state);
		assertEquals(31, dead.getDeathTick(BaOverviewNpcType.HEALER, 1).intValue());
		assertNull(dead.getPredictedDeathTick(BaOverviewNpcType.HEALER, 1));
	}

	private static BaHealerSyncMessage message(int predictedDeathTick, boolean unknownTtk, boolean healthRatioMode)
	{
		return new BaHealerSyncMessage(
				1,
				1,
				10,
				1,
				0,
				0,
				predictedDeathTick,
				unknownTtk,
				-1,
				false,
				healthRatioMode,
				new int[0]
		);
	}
}

package com.bahealerorder.healer.ttk;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class HealerTtkTrackerTest
{
	@Test
	public void waveOneSingleFoodDiesFromKnownMaxHp()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);

		assertEquals(27, tracker.getState(10).getMaxHp().intValue());
		assertEquals(30, deathTick(tracker, 10));
	}

	@Test
	public void waveTenSingleFoodCannotKillHealer()
	{
		HealerTtkTracker tracker = tracker(10);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);

		HealerTtkPrediction prediction = tracker.getPrediction(10);
		assertFalse(prediction.hasDeathTick());
		assertTrue(prediction.isUnknown());
	}

	@Test
	public void repeatedFoodRefreshesDamageAndSubtractsFoodDamage()
	{
		HealerTtkTracker tracker = tracker(10);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);
		tracker.onFoodConsumedForHealer(10, 25);

		assertEquals(2, tracker.getState(10).getConfirmedFoodCount());
		assertEquals(70, deathTick(tracker, 10));
	}

	@Test
	public void outOfOrderFoodEventsReplayChronologically()
	{
		HealerTtkTracker tracker = tracker(10);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 25);
		tracker.onFoodConsumedForHealer(10, 0);

		assertEquals(70, deathTick(tracker, 10));
	}

	@Test
	public void sameTickFoodEventsBothCount()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);

		assertEquals(25, deathTick(tracker, 10));
	}

	@Test
	public void sameTickRepoisonDoesNotEraseExistingPoisonHit()
	{
		HealerTtkTracker tracker = tracker(2);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);
		tracker.onFoodConsumedForHealer(10, 25);

		assertEquals(30, deathTick(tracker, 10));
	}

	@Test
	public void earlyFoodUsesGlobalWaveCadence()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 20);
		tracker.onFoodConsumedForHealer(10, 24);

		assertEquals(25, tracker.getState(10).getFirstPoisonTick());
		assertEquals(50, deathTick(tracker, 10));
	}

	@Test
	public void lateFoodUsesFoodRelativeCadence()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 20);
		tracker.onFoodConsumedForHealer(10, 26);

		assertEquals(31, tracker.getState(10).getFirstPoisonTick());
		assertEquals(56, deathTick(tracker, 10));
	}

	@Test
	public void invalidWaveDoesNotDisplayTtk()
	{
		HealerTtkTracker tracker = tracker(0);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);

		assertFalse(tracker.getPrediction(10).hasValue());
	}

	@Test
	public void observedHpDoesNotChangeDeterministicTtk()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);

		assertFalse(tracker.observeHp(10, 5, 17, 30));
		assertEquals(30, deathTick(tracker, 10));
	}

	@Test
	public void explicitSelectionSwitchesToHealthRatioEstimate()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);

		assertTrue(tracker.switchToHealthRatioTtk(10, 5, 17, 30));
		assertEquals(25, deathTick(tracker, 10));
	}

	@Test
	public void healthRatioSelectionBeforeFoodDoesNotSelectAMode()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 0);

		assertFalse(tracker.switchToHealthRatioTtk(10, 5, 27, 30));
		assertFalse(tracker.getPrediction(10).hasValue());

		tracker.onFoodConsumedForHealer(10, 10);
		assertEquals(40, deathTick(tracker, 10));
	}

	@Test
	public void healthRatioModeIsExplicit()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);

		assertFalse(tracker.isHealthRatioMode(10));
		tracker.switchToHealthRatioTtk(10, 5, 17, 30);

		assertTrue(tracker.isHealthRatioMode(10));
	}

	@Test
	public void healthRatioModeUpdatesFromLaterLowerHpObservation()
	{
		HealerTtkTracker tracker = tracker(1);
		tracker.onHealerSpawned(10, 0);
		tracker.onFoodConsumedForHealer(10, 0);
		tracker.switchToHealthRatioTtk(10, 5, 17, 30);

		assertEquals(25, deathTick(tracker, 10));
		assertTrue(tracker.observeHp(10, 10, 8, 30));
		assertEquals(20, deathTick(tracker, 10));
	}

	private static HealerTtkTracker tracker(int wave)
	{
		HealerTtkTracker tracker = new HealerTtkTracker();
		tracker.startWave(0, wave);
		return tracker;
	}

	private static int deathTick(HealerTtkTracker tracker, int npcIndex)
	{
		HealerTtkPrediction prediction = tracker.getPrediction(npcIndex);
		assertTrue(prediction.hasDeathTick());
		return prediction.getDeathTick();
	}
}

package com.bahealerorder.healer.ttk;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import java.util.OptionalInt;
import org.junit.Test;

public class HealerPoisonModelTest
{
	private final HealerPoisonModel model = new HealerPoisonModel();

	@Test
	public void poisonCannotKillMoreThanFiftyHp()
	{
		OptionalInt deathTick = model.calculateDeathTick(51, 100, 100, 100);

		assertFalse(deathTick.isPresent());
	}

	@Test
	public void poisonKillsFiveHpOnSecondPoisonHit()
	{
		OptionalInt deathTick = model.calculateDeathTick(5, 100, 100, 100);

		assertEquals(110, deathTick.getAsInt());
	}

	@Test
	public void poisonKillsFiftyHpOnLastPoisonHit()
	{
		OptionalInt deathTick = model.calculateDeathTick(50, 0, 0, 0);

		assertEquals(100, deathTick.getAsInt());
	}

	@Test
	public void laterFoodRefreshesDamageWithoutResettingCadence()
	{
		OptionalInt deathTick = model.calculateDeathTick(4, 100, 119, 119);

		assertEquals(120, deathTick.getAsInt());
	}

	@Test
	public void elapsedCurrentHpStartsFromNextFutureCadenceTick()
	{
		OptionalInt deathTick = model.calculateDeathTick(4, 100, 100, 106);

		assertEquals(110, deathTick.getAsInt());
	}
}

package com.bahealerorder.healer.codes;

import static org.junit.Assert.assertEquals;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class HealerCodeProgressTest
{
	@Test
	public void switchesToPostRestockTargetAfterFirstTargetIsFed()
	{
		WaveCode code = HealerCodeParser.parseWaveCode(null, "Restock Split", 8, false, "6,2");
		List<FeedEvent> feedEvents = new ArrayList<>();

		for (int i = 0; i < 6; i++)
		{
			feedEvents.add(new FeedEvent(1, i, 0));
		}

		HealerCodeStatus status = HealerCodeProgress.getDisplayStatus(code, 1, 0, feedEvents);

		assertEquals(2, status.getInstruction().getTargetFoodCount());
		assertEquals(0, status.getFoodFed());
		assertEquals(CodeDisplayState.IN_PROGRESS, status.getState());
		assertEquals(8, HealerCodeProgress.getExpectedFoodForOrder(code, 1, 0));

		feedEvents.add(new FeedEvent(1, 6, 0));
		status = HealerCodeProgress.getDisplayStatus(code, 1, 0, feedEvents);

		assertEquals(2, status.getInstruction().getTargetFoodCount());
		assertEquals(1, status.getFoodFed());
		assertEquals(CodeDisplayState.IN_PROGRESS, status.getState());
	}

	@Test
	public void beforeTimingUsesFirstFoodAndAfterTimingUsesLastFood()
	{
		WaveCode code = HealerCodeParser.parseWaveCode(null, "Timing", 8, false, "2[45](45)");
		List<FeedEvent> feedEvents = new ArrayList<>();
		feedEvents.add(new FeedEvent(1, 44, 0));
		feedEvents.add(new FeedEvent(1, 50, 0));

		HealerCodeStatus status = HealerCodeProgress.getDisplayStatus(code, 1, 0, feedEvents);

		assertEquals(CodeDisplayState.COMPLETE, status.getState());

		feedEvents.set(0, new FeedEvent(1, 45, 0));
		status = HealerCodeProgress.getDisplayStatus(code, 1, 0, feedEvents);
		assertEquals(CodeDisplayState.IN_PROGRESS, status.getState());
	}
}

package com.bahealerorder.healer.codes;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;

public class HealerCodeParserTest
{
	@Test
	public void parsesWindowInstruction()
	{
