		assertFalse(BaPartyChatExclusions.contains("Healer: Poison Tofu!"));
	}

	private static java.util.function.Predicate<String> inParty(String... names)
	{
		Set<String> partyNames = new HashSet<>(names == null ? Collections.emptyList() : Arrays.asList(names));
		return partyNames::contains;
	}

	private static MessageNode messageNode(ChatMessageType type, String name, String value, String sender)
	{
		return (MessageNode) Proxy.newProxyInstance(
				MessageNode.class.getClassLoader(),
				new Class<?>[]{MessageNode.class},
				(proxy, method, args) ->
				{
					if ("getType".equals(method.getName())) return type;
					if ("getName".equals(method.getName())) return name;
					if ("getValue".equals(method.getName())) return value;
					if ("getSender".equals(method.getName())) return sender;
					return defaultValue(method.getReturnType());
				}
		);
	}

	private static Client client(AtomicInteger tick)
	{
		return (Client) Proxy.newProxyInstance(
				Client.class.getClassLoader(),
				new Class<?>[]{Client.class},
				(proxy, method, args) -> "getTickCount".equals(method.getName()) ? tick.get() : defaultValue(method.getReturnType())
		);
	}

	private static Object defaultValue(Class<?> type)
	{
		if (!type.isPrimitive()) return null;
		if (type == boolean.class) return false;
		if (type == int.class) return 0;
		if (type == long.class) return 0L;
		if (type == float.class) return 0f;
		if (type == double.class) return 0d;
		if (type == byte.class) return (byte) 0;
		if (type == short.class) return (short) 0;
		if (type == char.class) return '\0';
		return null;
	}
}

package com.bahealerorder.common;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class BaWaveOverviewStateTest
{
	@Test
	public void recordsDeathTickForNpcOrder()
	{
		BaWaveOverviewState state = new BaWaveOverviewState();
		state.startWave(1);
		state.recordSpawn(BaOverviewNpcType.RANGER, 100);

		assertNull(state.getDeathTick(BaOverviewNpcType.RANGER, 1));
		assertTrue(state.recordDeath(BaOverviewNpcType.RANGER, 100, 12));
		assertTrue(state.isDead(BaOverviewNpcType.RANGER, 1));
		assertEquals(12, state.getDeathTick(BaOverviewNpcType.RANGER, 1).intValue());

		assertFalse(state.recordDeath(BaOverviewNpcType.RANGER, 100, 15));
		assertEquals(12, state.getDeathTick(BaOverviewNpcType.RANGER, 1).intValue());
	}

	@Test
	public void syncsDeathTickByNpcOrder()
	{
		BaWaveOverviewState source = new BaWaveOverviewState();
		BaWaveOverviewState target = new BaWaveOverviewState();

		source.startWave(1);
		source.recordSpawn(BaOverviewNpcType.FIGHTER, 200);
		source.recordDeath(BaOverviewNpcType.FIGHTER, 200, 18);

		target.updateFromParty(source.toSyncMessage(302));

		assertTrue(target.isDead(BaOverviewNpcType.FIGHTER, 1));
		assertEquals(18, target.getDeathTick(BaOverviewNpcType.FIGHTER, 1).intValue());
	}
}

package com.bahealerorder.defender;

import java.util.Locale;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Text;

final class DefenderInventory
{
	private static final String IMCANDO_HAMMER_NAME = "imcando hammer";

	private DefenderInventory()
	{
	}

	static boolean isHammer(int itemId, String itemName)
	{
		if (itemId == ItemID.HAMMER) return true;

		return isImcandoHammer(itemId, itemName);
	}

	static boolean isImcandoHammer(int itemId, String itemName)
	{
		if (itemId == ItemID.IMCANDO_HAMMER || itemId == ItemID.IMCANDO_HAMMER_OFFHAND) return true;

		return itemName != null
				&& Text.removeTags(itemName).toLowerCase(Locale.ROOT).contains(IMCANDO_HAMMER_NAME);
	}

}

