package com.bahealerorder.healer.ttk;

import java.util.OptionalInt;

final class HealthRatioHealerTtk
{
	private static final int FOOD_DAMAGE = 4;
	private static final HealerPoisonModel POISON_MODEL = new HealerPoisonModel();

	private int firstPoisonTick;
	private int lastFoodTick;
	private int currentHp;
	private int currentHpTick;

	HealthRatioHealerTtk(int currentHp, int currentHpTick, int firstPoisonTick, int lastFoodTick)
	{
		this.currentHp = currentHp;
		this.currentHpTick = currentHpTick;
		this.firstPoisonTick = firstPoisonTick;
		this.lastFoodTick = lastFoodTick;
	}

	void recordFoodConsumed(int tick, int firstPoisonTick)
	{
		currentHp = Math.max(currentHp - FOOD_DAMAGE, 0);
		currentHpTick = tick;
		this.firstPoisonTick = firstPoisonTick;
		lastFoodTick = Math.max(lastFoodTick, tick);
	}

	boolean observeHp(int tick, int hp)
	{
		if (hp >= currentHp) return false;

		currentHp = hp;
		currentHpTick = tick;
		return true;
	}

	OptionalInt calculateDeathTick()
	{
		return POISON_MODEL.calculateDeathTick(currentHp, firstPoisonTick, lastFoodTick, currentHpTick);
	}
}

package com.bahealerorder.healer.ttk;

import java.util.OptionalInt;

final class HealerHealthEstimator
{
	private HealerHealthEstimator()
	{
	}

	static OptionalInt estimate(int healthRatio, int healthScale, int maxHp)
	{
		if (maxHp <= 0 || healthRatio < 0 || healthScale <= 0) return OptionalInt.empty();

		if (healthRatio <= 0) return OptionalInt.of(0);

		int minHp = 1;
		int maxEstimatedHp;

		if (healthScale > 1)
		{
			if (healthRatio > 1)
			{
				minHp = (maxHp * (healthRatio - 1) + healthScale - 2) / (healthScale - 1);
			}

			maxEstimatedHp = Math.min((maxHp * healthRatio - 1) / (healthScale - 1), maxHp);
		}
		else
		{
			maxEstimatedHp = maxHp;
		}

		return OptionalInt.of((minHp + maxEstimatedHp + 1) / 2);
	}
}

package com.bahealerorder.healer.ttk;

import java.util.HashMap;
import java.util.Map;
import lombok.Getter;

public class HealerTtkTracker
{
	private static final int[] HEALER_MAX_HP_BY_WAVE = {0, 27, 32, 37, 43, 49, 55, 60, 67, 76, 60};

	private final Map<Integer, HealerTtkState> statesByNpcIndex = new HashMap<>();
	@Getter
	private int waveStartTick = -1;
	private int healerMaxHp = -1;

	public void startWave(int tick, int wave)
	{
		waveStartTick = tick;
		healerMaxHp = getHealerMaxHp(wave);
		statesByNpcIndex.clear();
	}

	public void reset()
	{
		waveStartTick = -1;
		healerMaxHp = -1;
		statesByNpcIndex.clear();
	}

	public void onHealerSpawned(int npcIndex, int tick)
	{
		statesByNpcIndex.compute(npcIndex, (key, state) ->
		{
			if (state == null) return new HealerTtkState(tick, healerMaxHp);

			state.updateSpawn(tick, healerMaxHp);
			return state;
		});
	}

	public void onFoodConsumedForHealer(int npcIndex, int tick)
	{
		HealerTtkState state = statesByNpcIndex.get(npcIndex);

		if (state != null)
		{
			state.recordFoodConsumed(tick, waveStartTick);
		}
	}

	public boolean observeHp(int npcIndex, int tick, int healthRatio, int healthScale)
	{
		return state(npcIndex, tick).observeHp(tick, healthRatio, healthScale);
	}

	public boolean switchToHealthRatioTtk(int npcIndex, int tick, int healthRatio, int healthScale)
	{
		return state(npcIndex, tick).switchToHealthRatioTtk(tick, healthRatio, healthScale);
	}

	public HealerTtkPrediction getPrediction(int npcIndex)
	{
		HealerTtkState state = statesByNpcIndex.get(npcIndex);
		return state == null ? HealerTtkPrediction.empty() : state.getPrediction();
	}

	public boolean isHealthRatioMode(int npcIndex)
	{
		HealerTtkState state = statesByNpcIndex.get(npcIndex);
		return state != null && state.isHealthRatioMode();
	}

	HealerTtkState getState(int npcIndex)
	{
		return statesByNpcIndex.get(npcIndex);
	}

	private HealerTtkState state(int npcIndex, int tick)
	{
		return statesByNpcIndex.computeIfAbsent(npcIndex, key -> new HealerTtkState(tick, healerMaxHp));
	}

	static int getHealerMaxHp(int wave)
	{
		return wave >= 1 && wave < HEALER_MAX_HP_BY_WAVE.length ? HEALER_MAX_HP_BY_WAVE[wave] : -1;
	}
}

package com.bahealerorder.healer.ttk;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.OptionalInt;
import lombok.AccessLevel;
import lombok.Getter;

final class DeterministicHealerTtk
{
	private static final int FOOD_DAMAGE = 4;
	private static final int UNKNOWN_TICK = -1;

	private final List<Integer> foodTicks = new ArrayList<>();
	private int spawnTick;
	@Getter(AccessLevel.PACKAGE)
	private int maxHp;
	@Getter(AccessLevel.PACKAGE)
	private int firstPoisonTick = UNKNOWN_TICK;
	@Getter(AccessLevel.PACKAGE)
	private int lastFoodTick = UNKNOWN_TICK;

	DeterministicHealerTtk(int spawnTick, int maxHp)
	{
		this.spawnTick = spawnTick;
		this.maxHp = maxHp;
	}

	void updateSpawn(int spawnTick, int maxHp)
	{
		this.spawnTick = spawnTick;
		this.maxHp = maxHp;
	}

	void recordFoodConsumed(int tick, int waveStartTick)
	{
		foodTicks.add(tick);
		Collections.sort(foodTicks);
		lastFoodTick = Math.max(lastFoodTick, tick);
		firstPoisonTick = calculateFirstPoisonTick(foodTicks.get(0), waveStartTick);
	}

	OptionalInt calculateDeathTick()
	{
		if (!hasPoisonModel()) return OptionalInt.empty();

		int hp = maxHp;
		int foodIndex = 0;
		int latestFoodTick = UNKNOWN_TICK;
		int poisonTick = firstPoisonTick;

		while (true)
		{
			int nextFoodTick = foodIndex < foodTicks.size() ? foodTicks.get(foodIndex) : Integer.MAX_VALUE;
			boolean poisonCanHit = latestFoodTick >= 0
					&& poisonTick <= latestFoodTick + HealerPoisonModel.TOTAL_POISON_HITS * HealerPoisonModel.TICKS_PER_POISON_HIT;
			int nextPoisonTick = poisonCanHit ? poisonTick : Integer.MAX_VALUE;

			if (nextFoodTick == Integer.MAX_VALUE && nextPoisonTick == Integer.MAX_VALUE) return OptionalInt.empty();

			if (nextPoisonTick <= nextFoodTick)
			{
				hp -= HealerPoisonModel.getDamageAtPoisonTick(latestFoodTick, poisonTick);
				if (hp <= 0) return OptionalInt.of(poisonTick);

				poisonTick += HealerPoisonModel.TICKS_PER_POISON_HIT;
				continue;
			}

			while (foodIndex < foodTicks.size() && foodTicks.get(foodIndex) == nextFoodTick)
			{
				hp -= FOOD_DAMAGE;
				latestFoodTick = nextFoodTick;
				foodIndex++;

				if (hp <= 0) return OptionalInt.of(nextFoodTick);
			}
		}
	}

	boolean hasPoisonModel()
	{
		return maxHp > 0 && !foodTicks.isEmpty() && firstPoisonTick >= 0 && lastFoodTick >= 0;
	}

	int getConfirmedFoodCount()
	{
		return foodTicks.size();
	}

	private int calculateFirstPoisonTick(int firstFoodTick, int waveStartTick)
	{
		if (waveStartTick >= 0 && firstFoodTick - spawnTick <= HealerPoisonModel.TICKS_PER_POISON_HIT)
		{
			int ticksSinceWaveStart = Math.max(firstFoodTick - waveStartTick, 0);
			return waveStartTick + (ticksSinceWaveStart / HealerPoisonModel.TICKS_PER_POISON_HIT + 1) * HealerPoisonModel.TICKS_PER_POISON_HIT;
		}

		return firstFoodTick + HealerPoisonModel.TICKS_PER_POISON_HIT;
	}
}

package com.bahealerorder.healer.ttk;

import java.util.OptionalInt;

class HealerTtkState
{
	private final DeterministicHealerTtk deterministicTtk;
	private HealthRatioHealerTtk healthRatioTtk;

	HealerTtkState(int spawnTick, int maxHp)
	{
		deterministicTtk = new DeterministicHealerTtk(spawnTick, maxHp);
	}

	void updateSpawn(int spawnTick, int maxHp)
	{
		deterministicTtk.updateSpawn(spawnTick, maxHp);
	}

	void recordFoodConsumed(int tick, int waveStartTick)
	{
		deterministicTtk.recordFoodConsumed(tick, waveStartTick);

		if (healthRatioTtk != null)
		{
			healthRatioTtk.recordFoodConsumed(tick, deterministicTtk.getFirstPoisonTick());
		}
	}

	boolean observeHp(int tick, int healthRatio, int healthScale)
	{
		if (healthRatioTtk == null) return false;

		OptionalInt estimatedHp = HealerHealthEstimator.estimate(healthRatio, healthScale, deterministicTtk.getMaxHp());
		return estimatedHp.isPresent() && healthRatioTtk.observeHp(tick, estimatedHp.getAsInt());
	}

	boolean switchToHealthRatioTtk(int tick, int healthRatio, int healthScale)
	{
		if (!deterministicTtk.hasPoisonModel()) return false;

		OptionalInt estimatedHp = HealerHealthEstimator.estimate(healthRatio, healthScale, deterministicTtk.getMaxHp());
		if (!estimatedHp.isPresent()) return false;

		HealerTtkPrediction previous = getPrediction();

		if (healthRatioTtk == null)
		{
			healthRatioTtk = new HealthRatioHealerTtk(
					estimatedHp.getAsInt(),
					tick,
					deterministicTtk.getFirstPoisonTick(),
					deterministicTtk.getLastFoodTick()
			);
		}
		else
		{
			healthRatioTtk.observeHp(tick, estimatedHp.getAsInt());
		}

		return !previous.equals(getPrediction());
	}

	HealerTtkPrediction getPrediction()
	{
		if (!deterministicTtk.hasPoisonModel()) return HealerTtkPrediction.empty();

		OptionalInt deathTick = healthRatioTtk == null
				? deterministicTtk.calculateDeathTick()
				: healthRatioTtk.calculateDeathTick();
		return deathTick.isPresent()
				? HealerTtkPrediction.known(deathTick.getAsInt())
				: HealerTtkPrediction.unknown();
	}

	boolean isHealthRatioMode()
	{
		return healthRatioTtk != null;
	}

	int getConfirmedFoodCount()
	{
		return deterministicTtk.getConfirmedFoodCount();
	}

	int getFirstPoisonTick()
	{
		return deterministicTtk.getFirstPoisonTick();
	}

	Integer getMaxHp()
	{
		return deterministicTtk.getMaxHp();
	}
}

