		activeEditorPanel = new JPanel();
		activeEditorPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(activeEditorPanel, CELL_WIDTH - 12, CELL_HEIGHT);
