	private void refreshSetCombo(String selectedId)
	{
		refreshing = true;
		try
		{
			setCombo.removeAllItems();
			setCombo.addItem(new BaPanelUi.ComboOption(null, "Select a tile marker set..."));
			for (TileMarkerSet set : strategyManager.getMarkerSets(waveMap))
			{
				setCombo.addItem(new BaPanelUi.ComboOption(set.getId(), set.toString(), set.isBuiltIn()));
			}
			selectSetComboValue(selectedId);
		}
		finally
		{
			refreshing = false;
		}
	}

	private void loadSet(String id)
	{
		TileMarkerSet set = strategyManager.findMarkerSet(id);
		if (set == null)
		{
			clearDraft();
			return;
		}

		refreshing = true;
		try
		{
			selectedSetId = set.getId();
			selectedSetBuiltIn = set.isBuiltIn();
			setName.setText(set.getName() == null ? "" : set.getName());
			selectSetComboValue(selectedSetId);
			mapMode = set.getMapMode();
			waveMap = set.getWaveMap();
			markers = TileMarker.copyAll(set.getMarkers());
			selectedMarkerIds.clear();
			mapZoom.setValue(defaultTileSize(mapMode));
			selectMapModeButton();
			selectWaveMapButton();
			refreshMarkerControls();
			resizeMap();
			dirty = false;
			updateSetControls();
			SwingUtilities.invokeLater(mapPanel::scrollToTrap);
		}
		finally
		{
			refreshing = false;
		}
	}

	private void clearDraft()
	{
		refreshing = true;
		try
		{
			selectedSetId = null;
			selectedSetBuiltIn = false;
			setName.setText("");
			mapMode = strategyManager.getLastMapMode();
			waveMap = strategyManager.getLastWaveMap();
			markers = new ArrayList<>();
			selectedMarkerIds.clear();
			selectSetComboValue(null);
			selectMapModeButton();
			selectWaveMapButton();
			refreshMarkerControls();
			mapZoom.setValue(defaultTileSize(mapMode));
			resizeMap();
			updateSetControls();
			dirty = false;
		}
		finally
		{
			refreshing = false;
		}
	}

	private void saveSet()
	{
		String name = setName.getText().trim();
		if (name.isEmpty())
		{
			Toolkit.getDefaultToolkit().beep();
			setName.requestFocusInWindow();
			return;
		}

		TileMarkerSet saved;
		if (selectedSetId != null
				&& !selectedSetBuiltIn
				&& strategyManager.updateMarkerSet(selectedSetId, name, mapMode, waveMap, TileMarker.copyAll(markers)))
		{
			saved = strategyManager.findMarkerSet(selectedSetId);
		}
		else
		{
			saved = strategyManager.createMarkerSet(name, mapMode, waveMap, TileMarker.copyAll(markers));
		}

		selectedSetId = saved.getId();
		selectedSetBuiltIn = false;
		setName.setText(saved.getName());
		refreshSetCombo(selectedSetId);
		dirty = false;
		updateSetControls();
		setsChanged.run();
	}

	private String promptNewMarkerSetName()
	{
		JTextField nameField = new JTextField();
		BaPanelUi.fixedSize(nameField, 260, CONTROL_HEIGHT);

		JPanel panel = BaPanelUi.verticalPanel(ColorScheme.DARKER_GRAY_COLOR);
		panel.add(label("Marker Set Name"));
		panel.add(Box.createVerticalStrut(5));
		panel.add(nameField);

		int result = JOptionPane.showConfirmDialog(this, panel, "New Marker Set", JOptionPane.OK_CANCEL_OPTION);
		if (result != JOptionPane.OK_OPTION) return null;

		String name = nameField.getText().trim();
		if (name.isEmpty())
		{
			Toolkit.getDefaultToolkit().beep();
			return null;
		}
		return name;
	}

	private void deleteSet()
	{
		if (selectedSetId == null) return;

		if (selectedSetBuiltIn)
		{
			Toolkit.getDefaultToolkit().beep();
			return;
		}

		List<String> strategyNames = strategyManager.getStrategyNamesUsingMarkerSet(selectedSetId);
		if (!strategyNames.isEmpty())
		{
			JOptionPane.showMessageDialog(
					this,
					"This tile marker set is used by these strategies:\n- "
							+ String.join("\n- ", strategyNames)
							+ "\n\nRemove it from those strategies or delete the strategies first.",
					"Marker Set In Use",
					JOptionPane.WARNING_MESSAGE
			);
			return;
		}

		int result = JOptionPane.showConfirmDialog(this, "Delete this tile marker set?", "Delete Marker Set", JOptionPane.OK_CANCEL_OPTION);
		if (result != JOptionPane.OK_OPTION) return;

		if (!strategyManager.deleteMarkerSet(selectedSetId)) return;
		refreshSetCombo(null);
		clearDraft();
		setsChanged.run();
	}

	private void exportSetToClipboard()
	{
		if (markers.isEmpty())
		{
			Toolkit.getDefaultToolkit().beep();
			return;
		}

		TileMarkerExportResult result = strategyManager.exportMarkerSetJson(currentDraftSet());
		if (result == null)
		{
			JOptionPane.showMessageDialog(this, "Current tile marker set could not be exported.", "Export Marker Set", JOptionPane.ERROR_MESSAGE);
			return;
		}

		BaClipboard.copyText(result.getJson());
		BaTransferDialog.show(
				this,
				"Export Marker Set",
				"Exported tile set " + result.getName() + " with " + result.getMarkerCount() + " tile markers.",
				"Export",
				result.getSummaryLines()
		);
	}

	private void importSetFromClipboard()
	{
		String json = BaClipboard.readText(this, "Import Marker Set");
		if (json == null) return;

		TileMarkerExportResult result;
		try
		{
			result = strategyManager.importMarkerExportJson(json, null);
		}
		catch (RuntimeException ex)
		{
			result = null;
		}

		if (result == null)
		{
			JOptionPane.showMessageDialog(this, "Clipboard text could not be imported as a tile marker export.", "Import Marker Set", JOptionPane.ERROR_MESSAGE);
			return;
		}

		refreshSetCombo(null);
		if ((result.getType() == TileMarkerExportType.MARKER_SET
				|| result.getType() == TileMarkerExportType.MARKER_SET_COLLECTION)
				&& result.getId() != null)
		{
			loadSet(result.getId());
		}
		setsChanged.run();
		BaTransferDialog.show(this, "Import Marker Set", markerSetImportMessage(result), "Import", result.getSummaryLines());
	}

	private String markerSetImportMessage(TileMarkerExportResult result)
	{
		if (result.getType() == TileMarkerExportType.MARKER_SET) return "Imported tile set " + result.getName() + " with " + result.getMarkerCount() + " tile markers.";
		return "Imported " + result.getTypedName() + ".";
	}

	private TileMarkerSet currentDraftSet()
	{
		return new TileMarkerSet(
				selectedSetBuiltIn ? null : selectedSetId,
				setName.getText().trim(),
				mapMode,
				waveMap,
				TileMarker.copyAll(markers),
				false
		);
	}

	public boolean hasUnsavedChanges()
	{
		return dirty;
	}

	public boolean confirmDiscard(Component parent)
	{
		if (!hasUnsavedChanges()) return true;

		int result = JOptionPane.showConfirmDialog(
				parent,
				"Discard unsaved tile marker set changes?",
				"Unsaved Changes",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE
		);
		return result == JOptionPane.YES_OPTION;
	}

	private void markDirty()
	{
		if (!refreshing)
		{
			dirty = true;
			updateSetControls();
		}
	}

	private void updateSetControls()
	{
		deleteSetButton.setEnabled(selectedSetId != null && !selectedSetBuiltIn);
		exportMarkersButton.setEnabled(!markers.isEmpty());
		saveMarkersButton.setEnabled(!markers.isEmpty() && !setName.getText().trim().isEmpty());
		boolean canApply = savedMarkerSetReady();
		applyInstructionLabel.setText("<html><div width='" + SIDE_WIDTH + "'>" + (canApply
				? "Select a wave and role to apply your markers to."
				: "Save your markers to apply them to a wave.") + "</div></html>");
		applyWaveCombo.setEnabled(canApply);
		applyRoleCombo.setEnabled(canApply);
		applyMarkersButton.setEnabled(canApply);
	}

	private void beginNewSet()
	{
		if (!confirmDiscard(this)) return;

		String name = promptNewMarkerSetName();
		if (name == null) return;

		TileMarkerSet saved = strategyManager.createMarkerSet(name, mapMode, waveMap, new ArrayList<>());
		refreshSetCombo(saved.getId());
		loadSet(saved.getId());
		setsChanged.run();
	}

	private void toggleLegend()
	{
		legendVisible = !legendVisible;
		strategyManager.setMarkerEditorLegendVisible(legendVisible);
		updateLegendButtonText();
		updateRightPanelLayout();
	}

	private void applyMarkersToStrategy()
	{
		if (!savedMarkerSetReady())
		{
			Toolkit.getDefaultToolkit().beep();
			return;
		}

		WaveOption wave = (WaveOption) applyWaveCombo.getSelectedItem();
		TileMarkerRoleContext role = (TileMarkerRoleContext) applyRoleCombo.getSelectedItem();
		if (wave == null || role == null)
		{
			Toolkit.getDefaultToolkit().beep();
			return;
		}

		TileMarkerSet set = strategyManager.findMarkerSet(selectedSetId);
		if (set == null || set.getWaveMap() != TileMarkerWaveMap.fromWave(wave.wave))
		{
			JOptionPane.showMessageDialog(
					this,
					"This marker set does not match the selected wave map.",
					"Apply Markers",
					JOptionPane.ERROR_MESSAGE
			);
			return;
		}

		strategyEditorOpener.open(wave.wave, role, selectedSetId);
	}

	private boolean savedMarkerSetReady()
	{
		return selectedSetId != null && !markers.isEmpty() && !dirty;
	}

	private void updateLegendButtonText()
	{
		legendToggleLink.setText(legendVisible ? "Hide Legend" : "Show Legend");
	}

	private void updateRightPanelLayout()
	{
		if (legendPanel != null)
		{
			legendPanel.setVisible(legendVisible);
		}
		boolean hasMarkers = !markers.isEmpty();
		if (helpPanel != null)
		{
			helpPanel.setVisible(!hasMarkers);
		}
		if (legendMarkerGap != null)
		{
			legendMarkerGap.setVisible(legendVisible);
		}

		revalidate();
		repaint();
	}

	private void setMapMode(TileMarkerMapMode mode)
	{
		if (refreshing || mode == null || mode == mapMode) return;

		mapMode = mode;
		strategyManager.setLastMapMode(mode);
		mapZoom.setValue(defaultTileSize(mode));
		resizeMap();
		refreshMarkerControls();
		markDirty();
		SwingUtilities.invokeLater(mapPanel::scrollToTrap);
	}

	private void setWaveMap(TileMarkerWaveMap map)
	{
		if (refreshing || map == null || map == waveMap) return;

		if (!confirmDiscard(this))
		{
			selectWaveMapButton();
			return;
		}

		waveMap = map;
		strategyManager.setLastWaveMap(map);
		refreshSetCombo(null);
		clearDraft();
		SwingUtilities.invokeLater(mapPanel::scrollToTrap);
	}

	private void handleTileClick(int mapX, int mapY, boolean delete)
	{
		TileMarkerMapLayout layout = waveMap.getLayout();
		if (!mapPanel.isSelectableMapTile(layout, mapX, mapY)) return;

		TileMarker existing = findMarkerAt(layout, mapX, mapY);
		if (existing != null)
		{
			if (delete)
			{
				deleteMarker(existing);
				return;
			}

			if (!selectedMarkerIds.remove(existing.getId()))
			{
				selectedMarkerIds.add(existing.getId());
			}
			refreshMarkerControls();
			return;
		}
		if (delete) return;

		TileMarker marker = new TileMarker(
				userMarkerId(mapX, mapY),
				layout.toTile(mapX, mapY),
				"",
				"",
				toHex(markerColor),
				getMarkerOpacityPercent(),
				getMarkerBorderWidth()
		);
		markers.add(marker);
		persistCurrentMarkerStyle();
		selectedMarkerIds.clear();
		selectedMarkerIds.add(marker.getId());
		refreshMarkerControls();
		mapPanel.repaint();
		markDirty();
	}

	private void refreshMarkerControls()
	{
		refreshing = true;
		try
		{
			markerCombo.removeAllItems();
			markerCombo.addItem(new MarkerOption(null, "Select a marker..."));
			TileMarkerMapLayout layout = waveMap.getLayout();
			for (TileMarker marker : markers)
			{
				if (layout.contains(marker.getTile()))
				{
					markerCombo.addItem(new MarkerOption(marker.getId(), getMarkerDisplayText(marker)));
				}
			}
			selectMarkerComboValue(getSelectedMarkerId());
		}
		finally
		{
			refreshing = false;
		}

		loadSelectedMarker();
		revalidate();
		repaint();
	}

	private void loadSelectedMarker()
	{
		TileMarker marker = getFirstSelectedMarker();
		boolean singleSelection = getSelectedMarker() != null;
		boolean wasRefreshing = refreshing;
		refreshing = true;

		try
		{
			if (marker == null)
			{
				markerName.setText("");
				markerLabel.setText("");
			}
			else
			{
				markerName.setText(singleSelection && marker.getName() != null ? marker.getName() : "");
				markerLabel.setText(singleSelection && marker.getLabel() != null ? marker.getLabel() : "");
				markerColor = TileMarkerStyle.parseColor(marker.getColor(), TileMarkerStyle.DEFAULT_MARKER_COLOR);
				markerOpacity.setValue(TileMarkerStyle.clampOpacityPercent(marker.getOpacityPercentOrDefault()));
				markerBorderWidth.setValue((double) TileMarkerStyle.clampBorderWidth(marker.getBorderWidthOrDefault()));
			}
		}
		finally
		{
			refreshing = wasRefreshing;
		}

		updateMarkerDetailEnabled();
		updateMarkerColorButton();
		mapPanel.repaint();
	}

	private void updateMarkerDetailEnabled()
	{
		boolean hasMarkers = !markers.isEmpty();
		boolean hasSelection = !selectedMarkerIds.isEmpty();
		boolean singleSelection = getSelectedMarker() != null;
		markerControlsPanel.setVisible(hasMarkers);
		markerCombo.setEnabled(hasMarkers);
		markerTextPanel.setVisible(true);
		markerName.setEnabled(singleSelection);
		markerLabel.setEnabled(singleSelection);
		markerColorButton.setEnabled(hasSelection);
		markerOpacity.setEnabled(hasSelection);
		markerBorderWidth.setEnabled(hasSelection);
		deleteMarkerButton.setEnabled(hasSelection);
		markerSelectionSummary.setText(selectionSummaryText());
		markerOpacityValue.setText(getMarkerOpacityPercent() + "%");
		updateSetControls();
		updateRightPanelLayout();
	}

	private void updateSelectedMarkerFromFields()
	{
		if (refreshing) return;

		TileMarker marker = getSelectedMarker();
		if (marker == null) return;

		marker.setName(markerName.getText().trim());
		marker.setLabel(markerLabel.getText().trim());
		updateMarkerComboLabel(marker);
		mapPanel.repaint();
		markDirty();
	}

	private void updateSelectedMarkerStyleFromFields()
	{
		markerOpacityValue.setText(getMarkerOpacityPercent() + "%");
		if (refreshing) return;

		List<TileMarker> selectedMarkers = getSelectedMarkers();
		if (!selectedMarkers.isEmpty())
		{
			for (TileMarker marker : selectedMarkers)
			{
				marker.setColor(toHex(markerColor));
				marker.setOpacityPercent(getMarkerOpacityPercent());
				marker.setBorderWidth(getMarkerBorderWidth());
			}
			mapPanel.repaint();
			markDirty();
		}

		persistCurrentMarkerStyle();
	}

	private void chooseMarkerColor()
	{
		RuneliteColorPicker colorPicker = colorPickerManager.create(this, markerColor, "Marker Color", true);
		colorPicker.setLocationRelativeTo(this);
		colorPicker.setOnColorChange(this::setMarkerColor);
		colorPicker.setOnClose(this::setMarkerColor);
		colorPicker.setVisible(true);
	}

	private void setMarkerColor(Color color)
	{
		if (color == null) return;

		markerColor = color;
		updateMarkerColorButton();
		updateSelectedMarkerStyleFromFields();
	}

	private void deleteSelectedMarker()
	{
		List<TileMarker> selectedMarkers = getSelectedMarkers();
		if (!selectedMarkers.isEmpty())
		{
			for (TileMarker marker : selectedMarkers)
			{
				markers.remove(marker);
			}
			selectedMarkerIds.clear();
			refreshMarkerControls();
			mapPanel.repaint();
			markDirty();
		}
	}

	private void deleteMarker(TileMarker marker)
	{
		markers.remove(marker);
		selectedMarkerIds.remove(marker.getId());
		refreshMarkerControls();
		mapPanel.repaint();
		markDirty();
	}

	private TileMarker getSelectedMarker()
	{
		String selectedMarkerId = getSelectedMarkerId();
		if (selectedMarkerId == null) return null;

		for (TileMarker marker : markers)
		{
			if (selectedMarkerId.equals(marker.getId())) return marker;
		}

		return null;
	}

	private TileMarker getFirstSelectedMarker()
	{
		for (TileMarker marker : markers)
		{
			if (selectedMarkerIds.contains(marker.getId())) return marker;
		}

		return null;
	}

	private List<TileMarker> getSelectedMarkers()
	{
		List<TileMarker> selectedMarkers = new ArrayList<>();
		for (TileMarker marker : markers)
		{
			if (selectedMarkerIds.contains(marker.getId()))
			{
				selectedMarkers.add(marker);
			}
		}
		return selectedMarkers;
	}

	private TileMarker findMarkerAt(TileMarkerMapLayout layout, int mapX, int mapY)
	{
		for (TileMarker marker : markers)
		{
			if (layout.contains(marker.getTile())
					&& layout.toMapX(marker.getTile()) == mapX
					&& layout.toMapY(marker.getTile()) == mapY)
			{
				return marker;
			}
		}

		return null;
	}

	private String getSelectedMarkerId()
	{
		return selectedMarkerIds.size() == 1 ? selectedMarkerIds.iterator().next() : null;
	}

	private String selectionSummaryText()
	{
		int count = selectedMarkerIds.size();
		if (count == 0) return "No markers selected";
		return count == 1 ? "1 marker selected" : count + " markers selected";
	}

	private String getMarkerDisplayText(TileMarker marker)
	{
		String name = marker.getName() == null ? "" : marker.getName().trim();
		if (!name.isEmpty()) return name;

		String label = marker.getLabel() == null ? "" : marker.getLabel().trim();
		return label.isEmpty() ? "Unnamed marker" : label;
	}

	private void updateMarkerComboLabel(TileMarker marker)
	{
		for (int i = 0; i < markerCombo.getItemCount(); i++)
		{
			MarkerOption item = markerCombo.getItemAt(i);
			if (marker.getId().equals(item.id))
			{
				item.label = getMarkerDisplayText(marker);
				markerCombo.repaint();
				return;
			}
		}
	}

	private void updateMarkerColorButton()
	{
		markerColorButton.setText(toHex(markerColor));
		markerColorButton.setBackground(markerColor);
		markerColorButton.setForeground(TileMarkerStyle.readableTextColor(markerColor));
	}

	private void persistCurrentMarkerStyle()
	{
		strategyManager.setLastMarkerStyle(toHex(markerColor), getMarkerOpacityPercent(), getMarkerBorderWidth());
	}

	private void zoomFromMouseWheel(MouseWheelEvent event)
	{
		int rotation = event.getWheelRotation();
		if (rotation != 0)
		{
			mapZoom.setValue(mapZoom.getValue() - rotation);
		}
		event.consume();
	}

	private void resizeMap()
	{
		Dimension mapSize = new Dimension(mapPanel.getMapWidthPixels(), mapPanel.getMapHeightPixels());
		mapPanel.setPreferredSize(mapSize);
		mapPanel.setMinimumSize(mapSize);
		mapScrollPane.getHorizontalScrollBar().setUnitIncrement(mapPanel.getTileSize());
		mapScrollPane.getVerticalScrollBar().setUnitIncrement(mapPanel.getTileSize());
		mapPanel.revalidate();
		mapPanel.repaint();
	}

	private void selectSetComboValue(String id)
	{
		BaPanelUi.selectComboValue(setCombo, id);
	}

	private void selectMarkerComboValue(String id)
	{
		for (int i = 0; i < markerCombo.getItemCount(); i++)
		{
			MarkerOption item = markerCombo.getItemAt(i);
			if ((id == null && item.id == null) || (id != null && id.equals(item.id)))
			{
				markerCombo.setSelectedIndex(i);
				return;
			}
		}

		if (markerCombo.getItemCount() > 0)
		{
			markerCombo.setSelectedIndex(0);
		}
	}

	private void selectMapModeButton()
	{
		for (java.util.Enumeration<javax.swing.AbstractButton> buttons = mapModeButtonGroup.getElements(); buttons.hasMoreElements(); )
		{
			javax.swing.AbstractButton button = buttons.nextElement();
			if (mapMode.getDisplayName().equals(button.getText()))
			{
				button.setSelected(true);
				return;
			}
		}
	}

	private void selectWaveMapButton()
	{
		for (java.util.Enumeration<javax.swing.AbstractButton> buttons = waveMapButtonGroup.getElements(); buttons.hasMoreElements(); )
		{
			javax.swing.AbstractButton button = buttons.nextElement();
			if (waveMap.getDisplayName().equals(button.getText()))
			{
				button.setSelected(true);
				return;
			}
		}
	}

	private int getMarkerOpacityPercent()
	{
		return TileMarkerStyle.clampOpacityPercent(markerOpacity.getValue());
	}

	private float getMarkerBorderWidth()
	{
		return TileMarkerStyle.clampBorderWidth(((Number) markerBorderWidth.getValue()).floatValue());
	}

	private String userMarkerId(int mapX, int mapY)
	{
		return "marker:" + waveMap.name() + ":" + mapMode.name() + ":" + mapX + ":" + mapY + ":" + System.nanoTime();
	}

	private static int defaultTileSize(TileMarkerMapMode mapMode)
	{
		if (mapMode.isFullArena()) return Math.max(MAP_MIN_TILE_SIZE, MAP_DEFAULT_TILE_SIZE - FULL_ARENA_DEFAULT_ZOOM_STEPS_OUT);

		return Math.min(MAP_MAX_TILE_SIZE, MAP_DEFAULT_TILE_SIZE + EAST_SIDE_DEFAULT_ZOOM_STEPS_IN);
	}

	private String toHex(Color color)
	{
		return TileMarkerStyle.toHex(color);
	}

	private JLabel label(String text)
	{
		return BaPanelUi.plainLabel(text, false);
	}

	private JLabel label(String text, boolean bold)
	{
		return BaPanelUi.plainLabel(text, bold);
	}

	interface StrategyEditorOpener
	{
		void open(int wave, TileMarkerRoleContext context, String markerSetId);
	}

	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static class WaveOption
	{
		private final int wave;

		@Override
		public String toString()
		{
			return "Wave " + wave;
		}
	}

	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static class MarkerOption
	{
		private final String id;
		private String label;

		@Override
		public String toString()
		{
			return label;
		}
	}
}

package com.bahealerorder.sidepanel.tilemarkers;

import com.bahealerorder.common.BaClipboard;
import com.bahealerorder.common.BaIcons;
import com.bahealerorder.sidepanel.BaPanelUi;
import com.bahealerorder.sidepanel.BaTransferDialog;
import com.bahealerorder.tilemarkers.GeneralTileMarkerStrategyManager;
import com.bahealerorder.tilemarkers.TileMarkerExportResult;
import com.bahealerorder.tilemarkers.TileMarkerExportType;
import com.bahealerorder.tilemarkers.TileMarkerRoleContext;
import com.bahealerorder.tilemarkers.TileMarkerStrategyPreset;
import com.bahealerorder.tilemarkers.TileMarkerWaveMap;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.Window;
import java.util.Collections;
import java.util.List;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.SwingUtil;

class TileMarkerStrategyPresetEditor extends JPanel
{
	private static final int CONTROL_HEIGHT = 24;
	private static final int EDITOR_WIDTH = 460;
	private static final int EDITOR_HEIGHT = 780;
	private static final int MARKER_SET_LIST_HEIGHT = 260;
	private static final int NOTES_HEIGHT = 150;
	private static final int TRASH_BUTTON_WIDTH = 24;
	private static final int HEADER_ROLE_WIDTH = 126;
	private static final int HEADER_WAVE_WIDTH = 76;
	private static final int STRATEGY_POPUP_WIDTH = 188;
	private static final String NOTES_TOOLTIP = "<html>Notes appear in the overlay panel, if enabled.<br>"
			+ "To use dynamic note highlighting, start a line with a wave time.<br>"
			+ "Example: 12.0 - Delay healer</html>";

	private final GeneralTileMarkerStrategyManager strategyManager;
	private final Runnable strategiesChanged;
	private final TileMarkerSetChecklistPanel markerSetChecklist;
	private final JComboBox<BaPanelUi.ComboOption> strategyCombo = BaPanelUi.fixedPopupWidthCombo(STRATEGY_POPUP_WIDTH);
	private final JTextField strategyName = new JTextField();
	private final JTextArea notes = new JTextArea();
	private final JButton deleteButton = new JButton(BaIcons.trashIcon());
	private final JComboBox<TileMarkerRoleContext> targetRoleCombo = new JComboBox<>();
	private final JComboBox<Integer> targetWaveCombo = new JComboBox<>();

	private TileMarkerWaveMap waveMap = TileMarkerWaveMap.WAVES_1_TO_9;
	private TileMarkerRoleContext targetRoleContext;
	private int targetWave;
	private String selectedStrategyId;
	private JDialog previewDialog;
	private boolean refreshing;
	private boolean dirty;

	TileMarkerStrategyPresetEditor(
			GeneralTileMarkerStrategyManager strategyManager,
			Runnable strategiesChanged,
			Runnable openMarkerEditor,
			String initialStrategyId,
			TileMarkerRoleContext targetRoleContext,
			int targetWave,
			String initialMarkerSetId)
	{
		this.strategyManager = strategyManager;
		this.strategiesChanged = strategiesChanged;
		this.targetRoleContext = targetRoleContext == null ? TileMarkerRoleContext.DEFENDER : targetRoleContext;
		this.targetWave = requireWave(targetWave);
		waveMap = TileMarkerWaveMap.fromWave(this.targetWave);
		TileMarkerStrategyPreset initialPreset = strategyManager.findStrategyPreset(initialStrategyId);

		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setLayout(new BorderLayout(0, 10));
		setPreferredSize(new Dimension(EDITOR_WIDTH + 20, EDITOR_HEIGHT));
		markerSetChecklist = new TileMarkerSetChecklistPanel(
				strategyManager,
				openMarkerEditor,
				this::markDirty,
				EDITOR_WIDTH,
				CONTROL_HEIGHT,
				MARKER_SET_LIST_HEIGHT
		);
		markerSetChecklist.setWaveMap(waveMap);

		add(createHeader(), BorderLayout.NORTH);
		add(createBody(), BorderLayout.CENTER);

		BaPanelUi.addTextChangeListener(strategyName, this::markDirty);
		BaPanelUi.addTextChangeListener(notes, this::markDirty);
		refreshStrategyCombo(initialPreset == null ? null : initialPreset.getId());
		if (initialPreset == null)
		{
			clearDraft(initialMarkerSetId);
		}
		else
		{
			loadStrategy(initialPreset.getId());
		}
	}

	private JPanel createHeader()
	{
		for (TileMarkerRoleContext context : TileMarkerRoleContext.values())
		{
			targetRoleCombo.addItem(context);
		}
		for (int wave = 1; wave <= 10; wave++)
		{
			targetWaveCombo.addItem(wave);
		}
		BaPanelUi.styleCombo(targetRoleCombo, HEADER_ROLE_WIDTH, CONTROL_HEIGHT);
		BaPanelUi.styleCombo(targetWaveCombo, HEADER_WAVE_WIDTH, CONTROL_HEIGHT);
		selectTargetComboValues();

			targetRoleCombo.addActionListener(event ->
		{
			if (refreshing) return;

			targetRoleContext = (TileMarkerRoleContext) targetRoleCombo.getSelectedItem();
		});
		targetWaveCombo.addActionListener(event -> changeTargetWave());

		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(row, EDITOR_WIDTH, CONTROL_HEIGHT);
		row.add(BaPanelUi.plainLabel("Configuring", true));
		row.add(Box.createHorizontalStrut(6));
		row.add(targetRoleCombo);
		row.add(Box.createHorizontalStrut(6));
		row.add(BaPanelUi.plainLabel("strategy for wave", true));
		row.add(Box.createHorizontalStrut(6));
		row.add(targetWaveCombo);
		row.add(Box.createHorizontalGlue());
		return row;
	}

	private void selectTargetComboValues()
	{
		refreshing = true;
		try
		{
			targetRoleCombo.setSelectedItem(targetRoleContext);
			targetWaveCombo.setSelectedItem(targetWave);
		}
		finally
		{
			refreshing = false;
		}
	}

	private void changeTargetWave()
	{
		if (refreshing) return;

		Integer selectedWave = (Integer) targetWaveCombo.getSelectedItem();
		if (selectedWave == null || selectedWave == targetWave) return;

		TileMarkerWaveMap nextWaveMap = TileMarkerWaveMap.fromWave(selectedWave);
		if (nextWaveMap != waveMap && !confirmDiscard(this))
		{
			selectTargetComboValues();
			return;
		}

		targetWave = selectedWave;
		if (nextWaveMap != waveMap)
		{
			waveMap = nextWaveMap;
			refreshStrategyCombo(null);
			clearDraft();
		}
	}

	private JPanel createBody()
	{
		JPanel panel = BaPanelUi.verticalPanel(ColorScheme.DARKER_GRAY_COLOR);
		panel.add(createStrategySelector());
		panel.add(Box.createVerticalStrut(28));
		panel.add(BaPanelUi.plainLabel("Name", true));
		panel.add(Box.createVerticalStrut(10));
		BaPanelUi.styleTextInput(strategyName, EDITOR_WIDTH, CONTROL_HEIGHT);
		panel.add(strategyName);
		panel.add(Box.createVerticalStrut(30));
		panel.add(markerSetChecklist);
		panel.add(Box.createVerticalStrut(30));
		panel.add(labelWithInfo("Notes"));
		panel.add(Box.createVerticalStrut(10));
		panel.add(createNotesArea());
		panel.add(Box.createVerticalStrut(28));
		panel.add(createActionRow());
		return panel;
	}

	private JPanel createStrategySelector()
	{
		BaPanelUi.styleCombo(strategyCombo, EDITOR_WIDTH - TRASH_BUTTON_WIDTH - 6, CONTROL_HEIGHT);
		strategyCombo.setRenderer(BaPanelUi.comboOptionRenderer(CONTROL_HEIGHT));
		strategyCombo.addActionListener(event ->
		{
			if (refreshing) return;

			if (!confirmDiscard(this))
			{
				refreshing = true;
				try
				{
					selectStrategyComboValue(selectedStrategyId);
				}
				finally
				{
					refreshing = false;
				}
				return;
			}

			BaPanelUi.ComboOption item = (BaPanelUi.ComboOption) strategyCombo.getSelectedItem();
			loadStrategy(item == null ? null : item.getId());
		});

		deleteButton.setToolTipText("Delete selected strategy");
		SwingUtil.removeButtonDecorations(deleteButton);
		BaPanelUi.fixedSize(deleteButton, TRASH_BUTTON_WIDTH, CONTROL_HEIGHT);
		deleteButton.addActionListener(event -> deleteStrategy());

		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(row, EDITOR_WIDTH, CONTROL_HEIGHT);
		row.add(strategyCombo, BorderLayout.CENTER);
		row.add(deleteButton, BorderLayout.EAST);
		return row;
	}

	private JScrollPane createNotesArea()
	{
		notes.setRows(4);
		notes.setLineWrap(true);
		notes.setWrapStyleWord(true);

		JScrollPane scrollPane = new JScrollPane(notes);
		scrollPane.setBorder(javax.swing.BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR));
		BaPanelUi.fixedSize(scrollPane, EDITOR_WIDTH, NOTES_HEIGHT);
		return scrollPane;
	}

	private JPanel createActionRow()
	{
		JPanel panel = BaPanelUi.verticalPanel(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(panel, EDITOR_WIDTH, CONTROL_HEIGHT * 2 + 8);

		int actionButtonWidth = (EDITOR_WIDTH - 16) / 3;
		JPanel row = new JPanel(new GridLayout(1, 3, 8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(row, EDITOR_WIDTH, CONTROL_HEIGHT);
		row.add(BaPanelUi.action("Import", this::importStrategyFromClipboard, actionButtonWidth, CONTROL_HEIGHT));
		row.add(BaPanelUi.action("Export", this::exportStrategyToClipboard, actionButtonWidth, CONTROL_HEIGHT));
		row.add(BaPanelUi.action("Preview", this::openStrategyPreview, actionButtonWidth, CONTROL_HEIGHT));

		panel.add(row);
		panel.add(Box.createVerticalStrut(8));
		panel.add(BaPanelUi.action("Save Strategy", this::saveStrategy, EDITOR_WIDTH, CONTROL_HEIGHT));
		return panel;
	}

	private void refreshStrategyCombo(String selectedId)
	{
		refreshing = true;
		try
		{
			strategyCombo.removeAllItems();
			strategyCombo.addItem(new BaPanelUi.ComboOption(null, "-- New --"));
			for (TileMarkerStrategyPreset preset : strategyManager.getStrategyPresets(waveMap))
			{
				strategyCombo.addItem(new BaPanelUi.ComboOption(preset.getId(), preset.toString(), preset.isBuiltIn()));
			}
			selectStrategyComboValue(selectedId);
		}
		finally
		{
			refreshing = false;
		}
	}

	private void loadStrategy(String id)
	{
		TileMarkerStrategyPreset preset = strategyManager.findStrategyPreset(id);
		if (preset == null)
		{
			clearDraft();
			return;
		}

		refreshing = true;
		try
		{
			selectedStrategyId = preset.getId();
			waveMap = TileMarkerWaveMap.fromWave(targetWave);
			strategyName.setText(preset.getName() == null ? "" : preset.getName());
			notes.setText(preset.getNotes() == null ? "" : preset.getNotes());
			markerSetChecklist.setWaveMap(waveMap);
			markerSetChecklist.setSelectedMarkerSetIds(preset.getMarkerSetIds());
			updateControls();
			dirty = false;
		}
		finally
		{
			refreshing = false;
		}
	}

	boolean selectStrategyForWave(
			String id,
			TileMarkerRoleContext roleContext,
			int wave,
			String initialMarkerSetId,
			Component parent)
	{
		if (!confirmDiscard(parent)) return false;

		targetRoleContext = roleContext == null ? TileMarkerRoleContext.DEFENDER : roleContext;
		targetWave = requireWave(wave);
		waveMap = TileMarkerWaveMap.fromWave(targetWave);
		selectTargetComboValues();
		TileMarkerStrategyPreset preset = strategyManager.findStrategyPreset(id);
		if (preset == null)
		{
			refreshStrategyCombo(null);
			clearDraft(initialMarkerSetId);
			return true;
		}

		refreshStrategyCombo(id);
		loadStrategy(id);
		return true;
	}

	private void clearDraft()
	{
		clearDraft(null);
	}

	private void clearDraft(String initialMarkerSetId)
	{
		refreshing = true;
		try
		{
			selectedStrategyId = null;
			strategyName.setText("");
			notes.setText("");
			markerSetChecklist.setWaveMap(waveMap);
			markerSetChecklist.setSelectedMarkerSetIds(isBlank(initialMarkerSetId)
					? Collections.emptyList()
					: Collections.singletonList(initialMarkerSetId));
			selectStrategyComboValue(null);
			updateControls();
			dirty = !isBlank(initialMarkerSetId);
		}
		finally
		{
			refreshing = false;
		}
	}

	void refreshMarkerSets()
	{
		refreshStrategyCombo(selectedStrategyId);
		markerSetChecklist.refresh();
	}

	private void saveStrategy()
	{
		TileMarkerStrategyPreset saved = strategyManager.saveStrategyPreset(
				selectedStrategyId,
				strategyName.getText(),
				notes.getText(),
				waveMap,
				collectSelectedMarkerSetIds()
		);
		if (saved == null)
		{
			Toolkit.getDefaultToolkit().beep();
			strategyName.requestFocusInWindow();
			return;
		}

		selectedStrategyId = saved.getId();
		strategyManager.setWaveSelectionStrategyId(targetRoleContext, targetWave, selectedStrategyId);
		refreshStrategyCombo(selectedStrategyId);
		updateControls();
		dirty = false;
		strategiesChanged.run();
		SwingUtilities.getWindowAncestor(this).dispose();
	}

	private void deleteStrategy()
	{
		if (selectedStrategyId == null)
		{
			Toolkit.getDefaultToolkit().beep();
			return;
		}

		TileMarkerStrategyPreset preset = strategyManager.findStrategyPreset(selectedStrategyId);
		if (preset == null || preset.isBuiltIn())
		{
			Toolkit.getDefaultToolkit().beep();
			return;
		}

		int result = JOptionPane.showConfirmDialog(this, "Delete this wave strategy?", "Delete Strategy", JOptionPane.OK_CANCEL_OPTION);
		if (result != JOptionPane.OK_OPTION) return;

		strategyManager.deleteStrategyPreset(selectedStrategyId);
		refreshStrategyCombo(null);
		clearDraft();
		strategiesChanged.run();
	}

	private void exportStrategyToClipboard()
	{
		TileMarkerExportResult result = strategyManager.exportStrategyPresetJson(draftStrategy());
		if (result == null)
		{
			JOptionPane.showMessageDialog(
					this,
					"Current wave strategy needs a name before it can be exported.",
					"Export Strategy",
					JOptionPane.ERROR_MESSAGE
			);
			return;
		}

		BaClipboard.copyText(result.getJson());
		BaTransferDialog.show(this, "Export Strategy", "Exported " + result.getTypedName() + ".", "Export", result.getSummaryLines());
	}

	private void importStrategyFromClipboard()
	{
		if (!confirmDiscard(this)) return;

		String json = BaClipboard.readText(this, "Import Strategy");
		if (json == null) return;

		TileMarkerExportResult result;
		try
		{
			result = strategyManager.importMarkerExportJson(json, waveMap);
		}
		catch (RuntimeException ex)
		{
			result = null;
		}

		if (result == null)
		{
			JOptionPane.showMessageDialog(
					this,
					"Clipboard text could not be imported as a " + waveMap.getDisplayName() + " tile marker export.",
					"Import Strategy",
					JOptionPane.ERROR_MESSAGE
			);
			return;
		}

		refreshStrategyCombo(result.getId());
		markerSetChecklist.refresh();
		if ((result.getType() == TileMarkerExportType.STRATEGY_PRESET
				|| result.getType() == TileMarkerExportType.STRATEGY_COLLECTION)
				&& result.getId() != null)
		{
			loadStrategy(result.getId());
		}
		strategiesChanged.run();
		BaTransferDialog.show(this, "Import Strategy", "Imported " + result.getTypedName() + ".", "Import", result.getSummaryLines());
	}

	boolean confirmDiscard(Component parent)
	{
		if (!dirty) return true;

		int result = JOptionPane.showConfirmDialog(
				parent,
				"Discard unsaved wave strategy changes?",
				"Unsaved Changes",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE
		);
		return result == JOptionPane.YES_OPTION;
	}

	private List<String> collectSelectedMarkerSetIds()
	{
		return markerSetChecklist.getSelectedMarkerSetIds();
	}

	private void openStrategyPreview()
	{
		if (previewDialog != null && previewDialog.isDisplayable())
		{
			previewDialog.dispose();
		}

		TileMarkerStrategyPreviewPanel previewPanel = new TileMarkerStrategyPreviewPanel(strategyManager, draftStrategy());
		Window owner = SwingUtilities.getWindowAncestor(this);
		previewDialog = new JDialog(owner, "Tile Marker Preview", java.awt.Dialog.ModalityType.MODELESS);
		previewDialog.setContentPane(previewPanel);
		previewDialog.pack();
		previewDialog.setMinimumSize(new Dimension(980, 720));
		previewDialog.setLocationRelativeTo(owner);
		previewDialog.setVisible(true);
	}

	private TileMarkerStrategyPreset draftStrategy()
	{
		return new TileMarkerStrategyPreset(
				selectedStrategyId,
				strategyName.getText().trim(),
				notes.getText(),
				waveMap,
				collectSelectedMarkerSetIds()
		);
	}

	private void selectStrategyComboValue(String id)
	{
		for (int i = 0; i < strategyCombo.getItemCount(); i++)
		{
			BaPanelUi.ComboOption item = strategyCombo.getItemAt(i);
			if ((id == null && item.getId() == null) || (id != null && id.equals(item.getId())))
			{
				strategyCombo.setSelectedIndex(i);
				return;
			}
		}

		if (strategyCombo.getItemCount() > 0)
		{
			strategyCombo.setSelectedIndex(0);
		}
	}

	private void updateControls()
	{
		TileMarkerStrategyPreset preset = strategyManager.findStrategyPreset(selectedStrategyId);
		deleteButton.setEnabled(preset != null && !preset.isBuiltIn());
	}

	private void markDirty()
	{
		if (!refreshing)
		{
			dirty = true;
		}
	}

	private JPanel labelWithInfo(String text)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(row, EDITOR_WIDTH, CONTROL_HEIGHT);

		JLabel info = new JLabel(BaIcons.infoIcon());
		info.setToolTipText(NOTES_TOOLTIP);
		row.add(BaPanelUi.plainLabel(text, true));
		row.add(Box.createHorizontalStrut(5));
		row.add(info);
		row.add(Box.createHorizontalGlue());
		return row;
	}

	private static int requireWave(int wave)
	{
		if (wave < 1 || wave > 10)
		{
			throw new IllegalArgumentException("Wave strategy editor requires wave 1-10.");
		}
		return wave;
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.isBlank();
	}

}

package com.bahealerorder.sidepanel.tilemarkers;

import com.bahealerorder.sidepanel.BaPanelUi;
import com.bahealerorder.tilemarkers.GeneralTileMarkerStrategyManager;
