@Singleton
public class WaveOverviewPanel extends JPanel
{
	private static final int CONTROL_HEIGHT = 24;
	private static final int CONTENT_WIDTH = PluginPanel.PANEL_WIDTH - 13;
	private static final int OVERVIEW_ICON_SIZE = 28;
	private static final int OVERVIEW_SKULL_ICON_SIZE = 14;
	private static final int OVERVIEW_MAX_SKULL_ICON_SIZE = 24;
	private static final int ROLE_ICON_SIZE = 18;
	private static final int OVERVIEW_CELL_HEIGHT = 50;
	private static final int OVERVIEW_CELL_GAP = 7;
	private static final int OVERVIEW_HEADER_GAP = 10;
	private static final int OVERVIEW_COLUMN_GAP = 4;
	private static final String OVERVIEW_ICON_RESOURCE_PATH = "/com/bahealerorder/overview/";
	private static final Font TITLE_FONT = FontManager.getRunescapeBoldFont();
	private static final Font LABEL_FONT = FontManager.getRunescapeSmallFont();
	private static final BaOverviewNpcType[] COLUMNS = {
			BaOverviewNpcType.RANGER,
			BaOverviewNpcType.FIGHTER,
			BaOverviewNpcType.RUNNER,
			BaOverviewNpcType.HEALER
	};

	private final SpriteManager spriteManager;
	private final ItemManager itemManager;
	private final BaUtilitiesConfig config;
	private final ConfigManager configManager;
	private final BaWaveOverviewStore store;
	private final BaRoleDetector roleDetector;
	private final BaWaveLifecycleService waveLifecycleService;
	private final GeneralTileMarkerStrategyManager strategyManager;
	private final HealerCodeManager healerCodeManager;
	private final WaveOverviewSelectorPanel selectorPanel;
	private final Map<BaOverviewNpcType, ImageIcon> overviewIcons = new EnumMap<>(BaOverviewNpcType.class);
	private final JLabel titleLabel = label("Wave Overview", true);
	private final JPanel contentPanel = BaPanelUi.verticalPanel(ColorScheme.DARKER_GRAY_COLOR, CONTENT_WIDTH - 16);

	private boolean loadingSkullIcon;
	private ImageIcon skullIcon;
	private String lastRenderSignature;

	@Inject
	public WaveOverviewPanel(
			SpriteManager spriteManager,
			ItemManager itemManager,
			BaUtilitiesConfig config,
			ConfigManager configManager,
			BaWaveOverviewStore store,
			BaRoleDetector roleDetector,
			BaWaveLifecycleService waveLifecycleService,
			GeneralTileMarkerStrategyManager strategyManager,
			HealerCodeManager healerCodeManager)
	{
		this.spriteManager = spriteManager;
		this.itemManager = itemManager;
		this.config = config;
		this.configManager = configManager;
		this.store = store;
		this.roleDetector = roleDetector;
		this.waveLifecycleService = waveLifecycleService;
		this.strategyManager = strategyManager;
		this.healerCodeManager = healerCodeManager;
		this.selectorPanel = new WaveOverviewSelectorPanel(store, this::createColumnMenuButton, () ->
		{
			lastRenderSignature = null;
			refreshAll();
		});

		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setAlignmentX(LEFT_ALIGNMENT);
		setMaximumSize(new Dimension(CONTENT_WIDTH, Integer.MAX_VALUE));
		add(createWaveOverviewSection());
		refreshAll();
	}

	public void refreshAll()
	{
		selectorPanel.refreshSelectors();
		BaWaveOverviewSnapshot snapshot = store.getSelectedSnapshot();
		String signature = buildRenderSignature(snapshot);

		if (signature.equals(lastRenderSignature)) return;

		lastRenderSignature = signature;
		titleLabel.setText(getTitleText(snapshot));

		contentPanel.removeAll();
		populateWaveOverviewContent(contentPanel, snapshot);
		revalidate();
		repaint();
	}

	private JPanel createWaveOverviewSection()
	{
		JPanel section = section();
		section.add(selectorPanel);
		section.add(Box.createVerticalStrut(6));
		section.add(contentPanel);
		return section;
	}

	private void populateWaveOverviewContent(JPanel section, BaWaveOverviewSnapshot snapshot)
	{
		List<BaOverviewNpcType> columns = getVisibleColumns();

		if (snapshot == null)
		{
			section.add(store.getSelectedRunId() == null
					? centeredMessage("Recent runs will appear here")
					: createRunMetadataPanel(store.getSelectedRun(), true));
			return;
		}

		if (columns.isEmpty())
		{
			section.add(centeredMessage("Use the menu above to choose which NPCs appear here."));
			addActiveNotes(section, snapshot);
			return;
		}

		JPanel table = new JPanel(new DynamicGridLayout(1, columns.size(), OVERVIEW_COLUMN_GAP, 0));
		int tableHeight = getWaveOverviewTableHeight(snapshot.getWave(), columns);
		table.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		table.setPreferredSize(new Dimension(CONTENT_WIDTH - 16, tableHeight));
		table.setMaximumSize(new Dimension(CONTENT_WIDTH - 16, tableHeight));
		table.setAlignmentX(LEFT_ALIGNMENT);

		for (BaOverviewNpcType type : columns)
		{
			table.add(createWaveOverviewColumn(snapshot, type, columns.size()));
		}

		section.add(table);

		if (snapshot.getDuration() != null)
		{
			section.add(Box.createVerticalStrut(6));
			section.add(BaPanelUi.centeredLabelRow(
					"Duration: " + snapshot.getDuration(), false, ColorScheme.DARKER_GRAY_COLOR, CONTENT_WIDTH, CONTROL_HEIGHT));
		}

		BaWaveOverviewRun selectedRun = store.getSelectedRun();
		if (selectedRun != null && selectedRun.getRoundDuration() != null)
		{
			section.add(Box.createVerticalStrut(12));
			section.add(createRunMetadataPanel(selectedRun, false));
		}

		addActiveNotes(section, snapshot);
	}

	private JPanel createWaveOverviewColumn(BaWaveOverviewSnapshot snapshot, BaOverviewNpcType type, int columnCount)
	{
		int columnWidth = getWaveOverviewColumnWidth(columnCount);
		JPanel panel = BaPanelUi.verticalPanel(ColorScheme.DARKER_GRAY_COLOR.darker());
		panel.setBorder(new EmptyBorder(4, 2, 4, 2));

		JLabel icon = new JLabel(loadOverviewIcon(type));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		BaPanelUi.fixedSize(icon, columnWidth, OVERVIEW_ICON_SIZE);
		panel.add(icon);
		panel.add(Box.createVerticalStrut(OVERVIEW_HEADER_GAP));

		List<String> labels = BaWaveInfo.getLabels(snapshot.getWave(), type);
		for (int i = 0; i < labels.size(); i++)
		{
			panel.add(createWaveOverviewEntry(snapshot, type, i + 1, formatWaveOverviewLabel(labels.get(i)), columnCount));
			panel.add(Box.createVerticalStrut(OVERVIEW_CELL_GAP));
		}

		return panel;
	}

	private String formatWaveOverviewLabel(String label)
	{
		if (label == null) return "";

		if (label.matches("^\\(R\\d+\\)$")) return label.substring(1, label.length() - 1);

		return label.replaceFirst("\\s*\\(R\\d+\\)$", "");
	}

	private JPanel createWaveOverviewEntry(BaWaveOverviewSnapshot snapshot, BaOverviewNpcType type, int order, String label, int columnCount)
	{
		EntryState entry = getEntryState(snapshot, type, order);
		int width = getWaveOverviewColumnWidth(columnCount);
		Color background = entry.spawned || entry.dead
				? ColorScheme.DARKER_GRAY_COLOR.darker()
				: ColorScheme.DARKER_GRAY_COLOR.darker().darker();

		JPanel content = BaPanelUi.verticalPanel(background);
		content.setBorder(new EmptyBorder(4, 0, 2, 0));
		BaPanelUi.fixedSize(content, width, OVERVIEW_CELL_HEIGHT);

		if (entry.dead)
		{
			int skullSize = getOverviewSkullIconSize(width);
			JLabel skull = centeredOverviewLabel("", entry.color, false, Math.max(CONTROL_HEIGHT - 6, skullSize), width);
			loadSkullIcon(skull, skullSize);
			content.add(skull);
			content.add(Box.createVerticalStrut(4));
		}
		else
		{
			content.add(centeredOverviewLabel(label, entry.labelColor, true, CONTROL_HEIGHT - 6, width));
		}

		if (entry.text != null && !entry.text.isEmpty())
		{
			JLabel text = centeredOverviewLabel(entry.text, entry.color, false, CONTROL_HEIGHT - 8, width);
			if (entry.dead)
			{
				text.setFont(getOverviewDeathFont(width));
			}
			content.add(text);
		}

		return content;
	}

	private EntryState getEntryState(BaWaveOverviewSnapshot snapshot, BaOverviewNpcType type, int order)
	{
		Integer deathTick = snapshot.getDeathTick(type, order);
		if (deathTick != null) return EntryState.dead(formatWaveTick(deathTick));

		Integer predictedDeathTick = snapshot.getPredictedDeathTick(type, order);
		if (predictedDeathTick != null) return EntryState.predicted(formatWaveTick(predictedDeathTick));

		if (snapshot.hasUnknownTtk(type, order)) return EntryState.predicted("?");

		return snapshot.hasSpawned(type, order) ? EntryState.spawned() : EntryState.pending();
	}

	private String formatWaveTick(int waveTick)
	{
		return String.format(java.util.Locale.ROOT, "%.1f", Math.max(0, waveTick) * 0.6d);
	}

	private JLabel centeredOverviewLabel(String text, Color color, boolean bold, int height, int width)
	{
		JLabel label = label(text, bold);
		label.setForeground(color);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		BaPanelUi.fixedSize(label, width, height);
		return label;
	}

	private JButton createColumnMenuButton()
	{
		JButton menuButton = new JButton(BaIcons.hamburgerIcon());
		menuButton.setToolTipText("Choose NPC columns");
		SwingUtil.removeButtonDecorations(menuButton);
		BaPanelUi.fixedSize(menuButton, CONTROL_HEIGHT + 4, CONTROL_HEIGHT);
		menuButton.addActionListener(event -> createColumnMenu().show(menuButton, 0, menuButton.getHeight()));
		return menuButton;
	}

	private JPopupMenu createColumnMenu()
	{
		JPopupMenu menu = new JPopupMenu();
		menu.add(columnMenuItem("Show Rangers", BaUtilitiesConfig.SHOW_OVERVIEW_RANGERS_KEY, config.showOverviewRangers()));
		menu.add(columnMenuItem("Show Fighters", BaUtilitiesConfig.SHOW_OVERVIEW_FIGHTERS_KEY, config.showOverviewFighters()));
		menu.add(columnMenuItem("Show Runners", BaUtilitiesConfig.SHOW_OVERVIEW_RUNNERS_KEY, config.showOverviewRunners()));
		menu.add(columnMenuItem("Show Healers", BaUtilitiesConfig.SHOW_OVERVIEW_HEALERS_KEY, config.showOverviewHealers()));
		return menu;
	}

	private JCheckBoxMenuItem columnMenuItem(String label, String key, boolean selected)
	{
		JCheckBoxMenuItem item = new JCheckBoxMenuItem(label, selected);
		item.addActionListener(event ->
		{
			configManager.setConfiguration(BaUtilitiesConfig.GROUP_NAME, key, item.isSelected());
			refreshAll();
		});
		return item;
	}

	private ImageIcon loadOverviewIcon(BaOverviewNpcType type)
	{
		ImageIcon icon = overviewIcons.get(type);

		if (icon != null) return icon;

		icon = new ImageIcon(new ImageIcon(getClass().getResource(OVERVIEW_ICON_RESOURCE_PATH + getIconResource(type)))
				.getImage()
				.getScaledInstance(OVERVIEW_ICON_SIZE, OVERVIEW_ICON_SIZE, Image.SCALE_SMOOTH));
		overviewIcons.put(type, icon);
		return icon;
	}

	private String getIconResource(BaOverviewNpcType type)
	{
		switch (type)
		{
			case RANGER:
				return "penance_ranger.png";
			case FIGHTER:
				return "penance_fighter.png";
			case RUNNER:
				return "penance_runner.png";
			case HEALER:
				return "penance_healer.png";
			default:
				throw new IllegalArgumentException("Unsupported NPC type " + type);
		}
	}

	private int getOverviewSkullIconSize(int columnWidth)
	{
		return Math.max(OVERVIEW_SKULL_ICON_SIZE, Math.min(OVERVIEW_MAX_SKULL_ICON_SIZE, columnWidth / 4));
	}

	private Font getOverviewDeathFont(int columnWidth)
	{
		float extraSize = Math.max(0f, Math.min(4f, (columnWidth - getWaveOverviewColumnWidth(COLUMNS.length)) / 18f));
		return LABEL_FONT.deriveFont(LABEL_FONT.getSize2D() + extraSize);
	}

	private void loadSkullIcon(JLabel label, int size)
	{
		if (skullIcon != null)
		{
			label.setIcon(getScaledSkullIcon(size));
			return;
		}

		if (loadingSkullIcon) return;

		loadingSkullIcon = true;
		spriteManager.getSpriteAsync(SpriteID.HEADICONS_PK, 0, image ->
				SwingUtilities.invokeLater(() ->
				{
					skullIcon = transparentIcon(image, OVERVIEW_MAX_SKULL_ICON_SIZE, 0.45f);
					lastRenderSignature = null;
					refreshAll();
				})
		);
	}

	private ImageIcon getScaledSkullIcon(int size)
	{
		if (skullIcon == null || size == OVERVIEW_MAX_SKULL_ICON_SIZE) return skullIcon;

		return new ImageIcon(skullIcon.getImage().getScaledInstance(size, size, Image.SCALE_SMOOTH));
	}

	private ImageIcon transparentIcon(BufferedImage image, int size, float alpha)
	{
		BufferedImage transparent = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = transparent.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		graphics.setComposite(AlphaComposite.SrcOver.derive(alpha));
		graphics.drawImage(image, 0, 0, size, size, null);
		graphics.dispose();
		return new ImageIcon(transparent);
	}

	private int getWaveOverviewColumnWidth(int columnCount)
	{
		return (CONTENT_WIDTH - 16 - OVERVIEW_COLUMN_GAP * (columnCount - 1)) / columnCount;
	}

	private int getWaveOverviewTableHeight(int wave, List<BaOverviewNpcType> columns)
	{
		int maxRows = 0;

		for (BaOverviewNpcType type : columns)
		{
			maxRows = Math.max(maxRows, BaWaveInfo.getExpectedCount(wave, type));
		}

		return OVERVIEW_ICON_SIZE + OVERVIEW_HEADER_GAP + (OVERVIEW_CELL_HEIGHT + OVERVIEW_CELL_GAP) * maxRows + 8;
	}

	private List<BaOverviewNpcType> getVisibleColumns()
	{
		List<BaOverviewNpcType> columns = new ArrayList<>();

		for (BaOverviewNpcType type : COLUMNS)
		{
			if (isColumnVisible(type))
			{
				columns.add(type);
			}
		}

		return columns;
	}

	private boolean isColumnVisible(BaOverviewNpcType type)
	{
		switch (type)
		{
			case RANGER:
				return config.showOverviewRangers();
			case FIGHTER:
				return config.showOverviewFighters();
			case RUNNER:
				return config.showOverviewRunners();
			case HEALER:
				return config.showOverviewHealers();
			default:
				return false;
		}
	}

	private String buildRenderSignature(BaWaveOverviewSnapshot snapshot)
	{
		BaWaveOverviewRun selectedRun = store.getSelectedRun();
		String activeNotes = getActiveNotes(snapshot);

		return store.getSelectedRunId()
				+ ":" + store.getSelectedWave()
				+ ":" + store.isSelectedWaveInProgress()
				+ ":" + getVisibleColumns()
				+ ":" + (skullIcon != null)
				+ ":" + (selectedRun == null ? "none" : selectedRun.metadataSignature())
				+ ":" + activeNotes
				+ ":" + getActiveStrategyName(snapshot)
				+ ":" + getActiveHealerCodeName(snapshot)
				+ ":" + (isBlank(activeNotes) ? "" : getCurrentWaveTick())
				+ ":" + (snapshot == null ? "none" : snapshot.signature());
	}

	private String getTitleText(BaWaveOverviewSnapshot snapshot)
	{
		if (!BaWaveInfo.isValidWave(snapshot == null ? -1 : snapshot.getWave())) return "Recent Runs";

		return store.isSelectedWaveInProgress()
				? "Wave " + snapshot.getWave() + " In Progress..."
				: "Wave " + snapshot.getWave() + " Overview";
	}

	private JPanel section()
	{
		return BaPanelUi.section(titleLabel, CONTENT_WIDTH, CONTROL_HEIGHT);
	}

	private JPanel centeredMessage(String text)
	{
		int height = getMessageHeight(text);
		JTextPane message = BaPanelUi.textBlock(text, CONTENT_WIDTH - 16, height, StyleConstants.ALIGN_CENTER);
		message.setFont(LABEL_FONT);

		JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(panel, CONTENT_WIDTH - 16, height);
		panel.add(message, BorderLayout.CENTER);
		return panel;
	}

	private void addActiveNotes(JPanel section, BaWaveOverviewSnapshot snapshot)
	{
		String notes = getActiveNotes(snapshot);
		if (isBlank(notes)) return;

		section.add(Box.createVerticalStrut(12));
		section.add(BaNotesPreviewPanel.create(
				getNotesHeading(snapshot), notes, getCurrentRoleColor(), CONTENT_WIDTH - 16, getCurrentWaveTick()));
	}

	private String getActiveNotes(BaWaveOverviewSnapshot snapshot)
	{
		if (snapshot == null || !store.isSelectedWaveInProgress()) return "";

		TileMarkerRoleContext context = getDisplayRoleContext();
		String notes = strategyManager.getActiveNotes(snapshot.getWave(), context);
		String codeText = getActiveHealerCodeText(snapshot);
		notes = notes == null ? "" : notes.trim();

		if (isBlank(codeText)) return notes;

		if (isBlank(notes)) return codeText;

		return codeText + "\n\n" + notes;
	}

	private String getNotesHeading(BaWaveOverviewSnapshot snapshot)
	{
		String codeName = getActiveHealerCodeName(snapshot);
		if (!isBlank(codeName)) return codeName;

		String strategyName = getActiveStrategyName(snapshot);
		return (isBlank(strategyName) ? "Strategy" : strategyName) + " Notes";
	}

	private String getActiveHealerCodeText(BaWaveOverviewSnapshot snapshot)
	{
		if (snapshot == null || !store.isSelectedWaveInProgress() || !roleDetector.isRole(BaRole.HEALER)) return "";

		WaveCode code = healerCodeManager.getActiveWaveCode(snapshot.getWave());
		return code == null ? "" : HealerCodeFormatter.formatDisplay(code).trim();
	}

	private String getActiveHealerCodeName(BaWaveOverviewSnapshot snapshot)
	{
		if (snapshot == null || !store.isSelectedWaveInProgress() || !roleDetector.isRole(BaRole.HEALER)) return "";

		WaveCode code = healerCodeManager.getActiveWaveCode(snapshot.getWave());
		return code == null ? "" : HealerCodeManager.waveCodeDisplayName(code);
	}

	private String getActiveStrategyName(BaWaveOverviewSnapshot snapshot)
	{
		if (snapshot == null || !store.isSelectedWaveInProgress()) return "";

		TileMarkerRoleContext context = getDisplayRoleContext();
		return strategyManager.getActiveStrategyName(snapshot.getWave(), context);
	}

	private Color getCurrentRoleColor()
	{
		Color color = BaRoleColors.color(getDisplayRole());
		return color == null ? BaRoleColors.HEALER : color;
	}

	private BaRole getDisplayRole()
	{
		BaRole role = roleDetector.getCurrentRole();
		return role == null ? BaRole.HEALER : role;
	}

	private TileMarkerRoleContext getDisplayRoleContext()
	{
		return TileMarkerRoleContext.fromRole(getDisplayRole());
	}

	private int getCurrentWaveTick()
	{
		return Math.max(0, Math.round(waveLifecycleService.getElapsedTimeMs() / 600f));
	}

	private JPanel createRunMetadataPanel(BaWaveOverviewRun run, boolean showMissingDuration)
	{
		if (run == null) return centeredMessage("Select a wave to view.");

		if (!showMissingDuration && run.getRoundDuration() == null) return BaPanelUi.verticalPanel(ColorScheme.DARKER_GRAY_COLOR);

		List<BaTeamMember> members = run.getTeamMembers();
		JPanel panel = BaPanelUi.verticalPanel(ColorScheme.DARKER_GRAY_COLOR);
		int height = Math.max(CONTROL_HEIGHT * 2, CONTROL_HEIGHT * (members.size() + 1) + (members.isEmpty() ? 0 : 10));
		BaPanelUi.fixedSize(panel, CONTENT_WIDTH - 16, height);

		for (BaTeamMember member : members)
		{
			panel.add(metadataMemberRow(member));
		}

		if (!members.isEmpty())
		{
			panel.add(Box.createVerticalStrut(10));
		}

		panel.add(roundDurationRow(run.getRoundDuration() == null ? "-" : run.getRoundDuration()));
		return panel;
	}

	private int getMessageHeight(String text)
	{
		int lines = text == null || text.isEmpty() ? 1 : text.split("\\R", -1).length;
		return Math.max(CONTROL_HEIGHT * 2, CONTROL_HEIGHT * lines);
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.isBlank();
	}

	private JPanel metadataMemberRow(BaTeamMember member)
	{
		JLabel nameLabel = label(member.getName(), false);
		nameLabel.setHorizontalAlignment(SwingConstants.LEFT);

		JPanel namePanel = new JPanel();
		namePanel.setLayout(new BoxLayout(namePanel, BoxLayout.X_AXIS));
		namePanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		namePanel.add(BaPanelUi.roleIconLabel(itemManager, member.getRole(), ROLE_ICON_SIZE, CONTROL_HEIGHT));
		namePanel.add(Box.createHorizontalStrut(5));
		namePanel.add(nameLabel);

		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(row, CONTENT_WIDTH - 16, CONTROL_HEIGHT);
		row.add(namePanel, BorderLayout.CENTER);

		return row;
	}

	private JPanel roundDurationRow(String duration)
	{
		JLabel label = label("Round duration: ", true);
		JLabel value = label(duration, true);
		value.setForeground(Color.ORANGE);

		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		BaPanelUi.fixedSize(row, CONTENT_WIDTH - 16, CONTROL_HEIGHT);
		row.add(label);
		row.add(value);
		return row;
	}

	private JLabel label(String text, boolean bold)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.TEXT_COLOR);
		label.setFont(bold ? TITLE_FONT : LABEL_FONT);
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static class EntryState
	{
		private final boolean spawned;
		private final boolean dead;
		private final Color labelColor;
		private final Color color;
		private final String text;

		private static EntryState pending()
		{
			return new EntryState(false, false, new Color(90, 90, 90), new Color(90, 90, 90), "");
		}

		private static EntryState spawned()
		{
			return new EntryState(true, false, ColorScheme.TEXT_COLOR, ColorScheme.TEXT_COLOR, "");
		}

		private static EntryState dead(String text)
		{
			return new EntryState(true, true, new Color(150, 150, 150), new Color(150, 150, 150), text);
		}

		private static EntryState predicted(String text)
		{
			return new EntryState(true, false, ColorScheme.TEXT_COLOR, Color.ORANGE, text);
		}
	}
}

package com.bahealerorder.common;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;

@Singleton
public class BaWaveOverviewState
{
	private final Map<BaOverviewNpcType, Set<Integer>> seenNpcIndexesByType = new EnumMap<>(BaOverviewNpcType.class);
	private final Map<BaOverviewNpcType, Map<Integer, Integer>> deathTickByNpcIndexByType = new EnumMap<>(BaOverviewNpcType.class);
	private final Map<BaOverviewNpcType, Map<Integer, Integer>> partyOrderByNpcIndexByType = new EnumMap<>(BaOverviewNpcType.class);
	private final Map<BaOverviewNpcType, Map<Integer, Integer>> partyDeathTickByOrderByType = new EnumMap<>(BaOverviewNpcType.class);
	private final Map<BaOverviewNpcType, Integer> indexBaseByType = new EnumMap<>(BaOverviewNpcType.class);
	private int wave = -1;

	public void reset()
	{
		wave = -1;
		seenNpcIndexesByType.clear();
		deathTickByNpcIndexByType.clear();
		partyOrderByNpcIndexByType.clear();
		partyDeathTickByOrderByType.clear();
		indexBaseByType.clear();
	}

	public boolean startWave(int wave)
	{
		if (!BaWaveInfo.isValidWave(wave)) return false;
		if (this.wave == wave) return false;

		reset();
		this.wave = wave;
		return true;
	}

	public int getWave()
	{
		return wave;
	}

	public boolean isWaveActive()
	{
		return BaWaveInfo.isValidWave(wave);
	}

	public boolean recordSpawn(BaOverviewNpcType type, int npcIndex)
	{
		if (!isTrackable(type) || npcIndex < 0) return false;

		Map<Integer, Integer> before = getOrderByNpcIndex(type);
		indexBaseByType.putIfAbsent(type, npcIndex);
		boolean added = seenNpcIndexes(type).add(npcIndex);
		return added || !before.equals(getOrderByNpcIndex(type));
	}

	public boolean recordDeath(BaOverviewNpcType type, int npcIndex, int deathTick)
	{
		if (!isTrackable(type) || npcIndex < 0 || deathTick < 0) return false;

		boolean changed = recordSpawn(type, npcIndex);
		changed |= putEarlierTick(deathTickByNpcIndex(type), npcIndex, deathTick);
		return changed;
	}

	public int getSpawnedCount(BaOverviewNpcType type)
	{
		return getSpawnedOrders(type).size();
	}

	public boolean hasSpawned(BaOverviewNpcType type, int order)
	{
		return getSpawnedOrders(type).contains(order);
	}

	public boolean isDead(BaOverviewNpcType type, int order)
	{
		return getDeathTick(type, order) != null;
	}

	public Integer getDeathTick(BaOverviewNpcType type, int order)
	{
		return getDeathTicksByOrder(type).get(order);
	}

	public boolean updateFromParty(BaWaveOverviewSyncMessage message)
	{
		if (message == null || message.getWave() <= 0) return false;

		boolean changed = startWave(message.getWave());
		changed |= recordPartyMappings(message.getNpcTypes(), message.getNpcIndexes(), message.getNpcOrders());
		changed |= recordPartyDeaths(message.getDeadNpcTypes(), message.getDeadNpcOrders(), message.getDeadNpcDeathTicks());
		return changed;
	}

	public BaWaveOverviewSyncMessage toSyncMessage(int world)
	{
		List<Integer> npcTypes = new ArrayList<>();
		List<Integer> npcIndexes = new ArrayList<>();
		List<Integer> npcOrders = new ArrayList<>();
		List<Integer> deadNpcTypes = new ArrayList<>();
		List<Integer> deadNpcOrders = new ArrayList<>();
		List<Integer> deadNpcDeathTicks = new ArrayList<>();

		for (BaOverviewNpcType type : BaOverviewNpcType.values())
		{
			if (type == BaOverviewNpcType.HEALER) continue;

			for (Map.Entry<Integer, Integer> entry : getOrderByNpcIndex(type).entrySet())
			{
				npcTypes.add(type.ordinal());
				npcIndexes.add(entry.getKey());
				npcOrders.add(entry.getValue());
			}

			for (Map.Entry<Integer, Integer> entry : getDeathTicksByOrder(type).entrySet())
			{
				deadNpcTypes.add(type.ordinal());
				deadNpcOrders.add(entry.getKey());
				deadNpcDeathTicks.add(entry.getValue());
			}
		}

		return new BaWaveOverviewSyncMessage(
				world,
				wave,
				toIntArray(npcTypes),
				toIntArray(npcIndexes),
				toIntArray(npcOrders),
				toIntArray(deadNpcTypes),
				toIntArray(deadNpcOrders),
				toIntArray(deadNpcDeathTicks)
		);
	}

	private boolean recordPartyMappings(int[] npcTypes, int[] npcIndexes, int[] npcOrders)
	{
		boolean changed = false;
		int count = Math.min(Math.min(length(npcTypes), length(npcIndexes)), length(npcOrders));

		for (int i = 0; i < count; i++)
		{
			BaOverviewNpcType type = typeFromOrdinal(npcTypes[i]);
			int npcIndex = npcIndexes[i];
			int order = npcOrders[i];

			if (!isTrackable(type) || npcIndex < 0 || !isValidOrder(type, order)) continue;

			Map<Integer, Integer> partyOrderByNpcIndex = partyOrderByNpcIndex(type);
			changed |= removeOrderFromOtherIndexes(partyOrderByNpcIndex, npcIndex, order);
			Integer previous = partyOrderByNpcIndex.put(npcIndex, order);
			changed |= previous == null || previous != order;
		}

		return changed;
	}

	private boolean recordPartyDeaths(int[] deadNpcTypes, int[] deadNpcOrders, int[] deadNpcDeathTicks)
	{
		boolean changed = false;
		int count = Math.min(Math.min(length(deadNpcTypes), length(deadNpcOrders)), length(deadNpcDeathTicks));

		for (int i = 0; i < count; i++)
		{
			BaOverviewNpcType type = typeFromOrdinal(deadNpcTypes[i]);
			int order = deadNpcOrders[i];
			int deathTick = deadNpcDeathTicks[i];

			if (!isTrackable(type) || !isValidOrder(type, order) || deathTick < 0) continue;

			changed |= putEarlierTick(partyDeathTickByOrder(type), order, deathTick);
		}

		return changed;
	}

	private Map<Integer, Integer> getOrderByNpcIndex(BaOverviewNpcType type)
	{
		if (!isTrackable(type)) return Collections.emptyMap();

		return NpcIndexOrderer.buildOrderByNpcIndex(
				seenNpcIndexes(type),
				partyOrderByNpcIndex(type),
				indexBaseByType.getOrDefault(type, -1),
				BaWaveInfo.getExpectedCount(wave, type)
		);
	}

	private Set<Integer> getSpawnedOrders(BaOverviewNpcType type)
	{
		return new HashSet<>(getOrderByNpcIndex(type).values());
	}

	private Map<Integer, Integer> getDeathTicksByOrder(BaOverviewNpcType type)
	{
		Map<Integer, Integer> deathTicksByOrder = new HashMap<>(partyDeathTickByOrder(type));
		Map<Integer, Integer> orderByNpcIndex = getOrderByNpcIndex(type);

		for (Map.Entry<Integer, Integer> entry : deathTickByNpcIndex(type).entrySet())
		{
			Integer order = orderByNpcIndex.get(entry.getKey());
			if (order != null)
			{
				putEarlierTick(deathTicksByOrder, order, entry.getValue());
			}
		}

		deathTicksByOrder.keySet().removeIf(order -> !isValidOrder(type, order));
		return deathTicksByOrder;
	}

	private Set<Integer> seenNpcIndexes(BaOverviewNpcType type)
	{
		return seenNpcIndexesByType.computeIfAbsent(type, ignored -> new HashSet<>());
	}

	private Map<Integer, Integer> deathTickByNpcIndex(BaOverviewNpcType type)
	{
		return deathTickByNpcIndexByType.computeIfAbsent(type, ignored -> new HashMap<>());
	}

	private Map<Integer, Integer> partyOrderByNpcIndex(BaOverviewNpcType type)
	{
		return partyOrderByNpcIndexByType.computeIfAbsent(type, ignored -> new HashMap<>());
	}

	private Map<Integer, Integer> partyDeathTickByOrder(BaOverviewNpcType type)
	{
		return partyDeathTickByOrderByType.computeIfAbsent(type, ignored -> new HashMap<>());
	}

	private boolean putEarlierTick(Map<Integer, Integer> deathTickByKey, int key, int deathTick)
	{
		Integer previousDeathTick = deathTickByKey.get(key);

		if (previousDeathTick != null && previousDeathTick <= deathTick) return false;

		deathTickByKey.put(key, deathTick);
		return true;
	}

	private boolean removeOrderFromOtherIndexes(Map<Integer, Integer> orderByNpcIndex, int npcIndex, int order)
	{
		boolean changed = false;

		for (Map.Entry<Integer, Integer> entry : new ArrayList<>(orderByNpcIndex.entrySet()))
		{
			if (entry.getKey() != npcIndex && entry.getValue() == order)
			{
				orderByNpcIndex.remove(entry.getKey());
				changed = true;
			}
		}

		return changed;
	}

	private boolean isTrackable(BaOverviewNpcType type)
	{
		return type != null && type != BaOverviewNpcType.HEALER && isWaveActive();
	}

	private boolean isValidOrder(BaOverviewNpcType type, int order)
	{
		return order > 0 && order <= BaWaveInfo.getExpectedCount(wave, type);
	}

	private BaOverviewNpcType typeFromOrdinal(int ordinal)
	{
		BaOverviewNpcType[] values = BaOverviewNpcType.values();
		return ordinal < 0 || ordinal >= values.length ? null : values[ordinal];
	}

	private int length(int[] values)
	{
		return values == null ? 0 : values.length;
	}

	private int[] toIntArray(List<Integer> values)
	{
		int[] array = new int[values.size()];
		for (int i = 0; i < values.size(); i++)
		{
			array[i] = values.get(i);
		}
		return array;
	}
}

package com.bahealerorder.common;

import com.bahealerorder.BaUtilitiesConfig;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.Text;

@Singleton
public class BaDispenserMenuService
{
	private final Client client;
	private final BaUtilitiesConfig config;
	private final BaRoleDetector roleDetector;

	@Inject
	private BaDispenserMenuService(Client client, BaUtilitiesConfig config, BaRoleDetector roleDetector)
	{
		this.client = client;
		this.config = config;
		this.roleDetector = roleDetector;
	}

	public void apply()
	{
		BaRole role = roleDetector.getCurrentRole();

		if (!config.deprioritizeOtherDispensers() || role == null) return;

		MenuEntry[] menuEntries = client.getMenu().getMenuEntries();

		if (menuEntries.length == 0) return;

		List<MenuEntry> filteredEntries = new ArrayList<>(menuEntries.length);
		boolean changed = false;

		for (MenuEntry entry : menuEntries)
		{
			if (isOtherRoleDispenser(entry, role))
			{
				changed = true;
				continue;
			}

			filteredEntries.add(entry);
		}

		if (changed)
		{
			client.getMenu().setMenuEntries(filteredEntries.toArray(new MenuEntry[0]));
		}
	}

	private boolean isOtherRoleDispenser(MenuEntry entry, BaRole role)
	{
		String target = entry.getTarget();

		if (target == null) return false;

		String targetText = Text.removeTags(target).toLowerCase(Locale.ROOT);

		for (BaRole dispenserRole : BaRole.values())
		{
			if (dispenserRole != role && targetText.contains(dispenserRole.getDispenserName().toLowerCase(Locale.ROOT))) return true;
		}

		return false;
	}
}

package com.bahealerorder.common;

import java.awt.Color;
