package com.bahealerorder.common;

import java.awt.Color;

public final class TileMarkerStyle
{
	public static final Color DEFAULT_MARKER_COLOR = new Color(80, 170, 255);
	public static final int MIN_OPACITY_PERCENT = 0;
	public static final int MAX_OPACITY_PERCENT = 100;
	public static final float MIN_BORDER_WIDTH = 0f;
	public static final float MAX_BORDER_WIDTH = 8f;

	private TileMarkerStyle()
	{
	}

	public static Color parseColor(String color, Color fallback)
	{
		try
		{
			return color == null || color.isBlank() ? fallback : Color.decode(color);
		}
		catch (RuntimeException ex)
		{
			return fallback;
		}
	}

	public static Color withOpacity(Color color, int opacityPercent)
	{
		Color value = color == null ? DEFAULT_MARKER_COLOR : color;
		return new Color(value.getRed(), value.getGreen(), value.getBlue(), alphaFromOpacity(opacityPercent));
	}

	public static int alphaFromOpacity(int opacityPercent)
	{
		return Math.round(255 * clampOpacityPercent(opacityPercent) / 100f);
	}

	public static int clampOpacityPercent(int opacityPercent)
	{
		return Math.max(MIN_OPACITY_PERCENT, Math.min(MAX_OPACITY_PERCENT, opacityPercent));
	}

	public static float clampBorderWidth(float borderWidth)
	{
		return Math.max(MIN_BORDER_WIDTH, Math.min(MAX_BORDER_WIDTH, borderWidth));
	}

	public static Color readableTextColor(Color background)
	{
		Color value = background == null ? DEFAULT_MARKER_COLOR : background;
		return (value.getRed() * 299 + value.getGreen() * 587 + value.getBlue() * 114) / 1000 > 140
				? Color.BLACK
				: Color.WHITE;
	}

	public static String toHex(Color color)
	{
		Color value = color == null ? DEFAULT_MARKER_COLOR : color;
		return String.format("#%02x%02x%02x", value.getRed(), value.getGreen(), value.getBlue());
	}
}

package com.bahealerorder.common;

import com.bahealerorder.BaUtilitiesConfig;
import com.bahealerorder.healer.HealerController;
import com.bahealerorder.tilemarkers.GeneralTileMarkerStrategyManager;
import com.bahealerorder.tilemarkers.TimedStrategyNote;
import com.bahealerorder.tilemarkers.TimedStrategyNotes;
import com.bahealerorder.tilemarkers.TileMarkerRoleContext;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.ColorUtil;

@Singleton
public class BaRolePanelOverlay extends OverlayPanel implements MouseListener
{
    private static final Color DEFAULT_PANEL_BACKGROUND = ComponentConstants.STANDARD_BACKGROUND_COLOR;
	private static final Color TITLE_COLOR = new Color(0, 255, 0);
	private static final Color TEXT_COLOR = Color.WHITE;
	private static final Color TTK_COLOR = Color.ORANGE;
	private static final Color DEAD_COLOR = Color.GRAY;

    private static final int BASE_OVERLAY_TEXT_SIZE = 16;
    private static final int BASE_PANEL_WIDTH = 240;
    private static final int BASE_MAX_HEALER_COLUMNS = 4;
    private static final int BASE_COLUMN_LABEL_WIDTH = 44;
    private static final int BASE_COLUMN_CELL_WIDTH = 60;
    private static final int BASE_ROW_LABEL_WIDTH = 60;
    private static final int BASE_ROW_CELL_WIDTH = 60;
    private static final int BASE_MAX_CELL_CHARS = 11;
    private static final int BASE_TOGGLE_BUTTON_WIDTH = 24;

    @Inject
    private BaUtilitiesConfig config;

    @Inject
    private Client client;

    @Inject
    private ConfigManager configManager;

    @Inject
    private BaRoleDetector roleDetector;

    @Inject
    private GeneralTileMarkerStrategyManager strategyManager;

    private HealerController healerController;
    private boolean codeTogglePressed;
    private final Rectangle codeToggleBounds = new Rectangle();
    private LineComponent codeToggleLine;

    @Inject
    private BaRolePanelOverlay()
    {
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(BASE_PANEL_WIDTH, 0));
        panelComponent.setBackgroundColor(DEFAULT_PANEL_BACKGROUND);
    }

    public void setHealerController(HealerController controller)
    {
        this.healerController = controller;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showOverlayPanel() || healerController == null) return hidePanel();

        if (getDisplayWave() <= 0) return hidePanel();

        BaUtilitiesConfig.FoodPanelStyle panelStyle = healerController.getFoodPanelStyle();
        String sourceText = healerController.getWaveCodeDisplaySource(getDisplayWave());
        String notes = getCurrentWaveNotes();
        boolean healerContent = shouldRenderHealerContent(panelStyle, sourceText);
        boolean notesContent = !isBlank(notes);

        if (!healerContent && !notesContent) return hidePanel();

        Font originalFont = preparePanel(graphics);

        try
        {
            addTitle(getPanelTitle(), getPanelTitleColor());

            if (!healerContent)
            {
                addCurrentWaveNotes(false);
                return renderPanel(graphics);
            }

			List<Integer> healerOrders = healerController.getHealerOrdersForWave(getDisplayWave());

            if (panelStyle == BaUtilitiesConfig.FoodPanelStyle.CODE_ONLY)
            {
                addCurrentWaveCodeAndNotes(false);
                return renderPanel(graphics);
            }

            if (panelStyle == BaUtilitiesConfig.FoodPanelStyle.SIMPLIFIED)
            {
                addSimplifiedRows(healerOrders);
                addCurrentWaveCodeAndNotesIfHealer(true);
                return renderPanel(graphics);
            }

            if (panelStyle == BaUtilitiesConfig.FoodPanelStyle.COLUMNS)
            {
                addColumnTables(graphics, healerOrders);
                addCurrentWaveCodeAndNotesIfHealer(true);
                return renderPanel(graphics);
            }

            if (healerController.hasActiveWaveCode(getDisplayWave()))
            {
                addHealerCallRows(graphics, healerOrders);
            }
            else
            {
                addHealerRows(healerOrders);
            }

            addCurrentWaveCodeAndNotesIfHealer(true);

            return renderPanel(graphics);
        }
        finally
        {
            graphics.setFont(originalFont);
        }
    }

    private boolean shouldRenderHealerContent(BaUtilitiesConfig.FoodPanelStyle panelStyle, String sourceText)
    {
        return healerController.isHealerRole()
                && panelStyle != BaUtilitiesConfig.FoodPanelStyle.NONE
                && (panelStyle != BaUtilitiesConfig.FoodPanelStyle.CODE_ONLY || !isBlank(sourceText));
    }

    private Font preparePanel(Graphics2D graphics)
    {
        Font originalFont = graphics.getFont();
        applyConfiguredFont(graphics, originalFont);
        clearPanelState();
        panelComponent.setBackgroundColor(getPanelBackgroundColor());
        panelComponent.setPreferredSize(new Dimension(scale(BASE_PANEL_WIDTH), 0));
        return originalFont;
    }

    private void applyConfiguredFont(Graphics2D graphics, Font defaultFont)
    {
        BaUtilitiesConfig.OverlayFont overlayFont = config.overlayFont();
        int textSize = getOverlayTextSize();

        if (overlayFont == BaUtilitiesConfig.OverlayFont.ARIAL)
        {
            graphics.setFont(new Font("Arial", Font.PLAIN, textSize));
            return;
        }

        if (overlayFont == BaUtilitiesConfig.OverlayFont.ARIAL_BOLD)
        {
            graphics.setFont(new Font("Arial", Font.BOLD, textSize));
            return;
        }

        if (textSize != BASE_OVERLAY_TEXT_SIZE)
        {
            graphics.setFont(defaultFont.deriveFont((float) textSize));
        }
    }

    private Dimension hidePanel()
    {
        codeTogglePressed = false;
        clearPanelState();
        return null;
    }

    private void clearPanelState()
    {
        panelComponent.getChildren().clear();
        codeToggleBounds.setBounds(0, 0, 0, 0);
        codeToggleLine = null;
    }

    private Dimension renderPanel(Graphics2D graphics)
    {
        Dimension dimension = super.render(graphics);

        if (codeToggleLine != null)
        {
            codeToggleBounds.setBounds(codeToggleLine.getBounds());
            codeToggleBounds.translate(getBounds().x, getBounds().y);
            codeToggleBounds.width = Math.min(scale(BASE_TOGGLE_BUTTON_WIDTH), codeToggleBounds.width);
        }

        return dimension;
    }

	private void addTitle(String text, Color color)
	{
		panelComponent.getChildren().add(
				TitleComponent.builder()
						.text(text)
						.color(color)
						.build()
		);
	}

	private void addLine(String text)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(text).build());
	}

	private void addLine(String text, Color color)
	{
		panelComponent.getChildren().add(
				LineComponent.builder()
						.left(text)
						.leftColor(color)
						.build()
		);
	}

    private int getOverlayTextSize()
    {
        return Math.max(8, config.foodPanelOverlayTextSize());
    }

    private double getOverlayScale()
    {
        return getOverlayTextSize() / (double) BASE_OVERLAY_TEXT_SIZE;
    }

    private int scale(int value)
    {
        return Math.max(1, (int) Math.round(value * getOverlayScale()));
    }

    private int getMaxCellChars()
    {
        return Math.max(6, (int) Math.round(BASE_MAX_CELL_CHARS * getOverlayScale()));
    }

    private Color getPanelBackgroundColor()
    {
        Color color = config.foodPanelOverlayBackgroundColor();
        return color == null ? DEFAULT_PANEL_BACKGROUND : color;
    }

	private String getPanelTitle()
	{
        String title = "Wave";
		int wave = getDisplayWave();

        if (wave > 0)
        {
            title = "Wave " + wave;
        }

        String codeName = healerController.isHealerRole() && healerController.hasActiveWaveCode(wave)
				? healerController.getWaveCodeName(wave)
				: null;
        String detail = !isBlank(codeName) ? codeName : getCurrentStrategyName();

        if (!isBlank(detail))
        {
            title += " - " + detail;
        }

        return title;
	}

	private Color getPanelTitleColor()
	{
		Color color = BaRoleColors.color(getDisplayRole());
		return color == null ? TITLE_COLOR : color;
	}

	private BaRole getDisplayRole()
	{
		BaRole role = roleDetector.getCurrentRole();
		return role == null ? BaRole.HEALER : role;
	}

	private String getCurrentStrategyName()
	{
		return strategyManager.getActiveStrategyName(
				getDisplayWave(),
				getCurrentRoleContext()
		);
	}

    private void addSimplifiedRows(List<Integer> healerOrders)
    {
        for (int healerOrder : healerOrders)
        {
            boolean spawned = healerController.hasHealerSpawned(healerOrder);
            boolean displayDead = healerController.isHealerDead(healerOrder);
            Color healerColor = getHealerColor(spawned, displayDead);
            String deathTime = getDeathTimeText(healerOrder);
            String text = ColorUtil.prependColorTag(healerController.getFoodPanelHealerLabel(getDisplayWave(), healerOrder), healerColor)
                    + " "
                    + ColorUtil.prependColorTag("(" + deathTime + ")", getDeathTimeColor(healerOrder, deathTime));

            addLine(text);
        }
    }

    private void addHealerRows(List<Integer> healerOrders)
    {
        for (int healerOrder : healerOrders)
        {
            String countText = healerController.getFoodPanelText(getDisplayWave(), healerOrder, -1);
            boolean spawned = healerController.hasHealerSpawned(healerOrder);
            boolean displayDead = healerController.isHealerDead(healerOrder);
            Color rowColor = getHealerColor(spawned, displayDead);
            Color rightColor = spawned && !displayDead ? healerController.getFoodPanelTextColor(getDisplayWave(), healerOrder, -1) : getHealerColor(spawned, displayDead);
            String ttkText = healerController.getHealerPanelTtkText(getDisplayWave(), healerOrder);

            if (rightColor == null)
            {
                rightColor = getHealerColor(spawned, displayDead);
            }

            if (ttkText != null && !ttkText.isEmpty())
            {
                countText += " " + ColorUtil.prependColorTag("(" + ttkText + ")", TTK_COLOR);
            }

            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left(healerController.getFoodPanelHealerLabel(getDisplayWave(), healerOrder))
                            .leftColor(rowColor)
                            .right(countText)
                            .rightColor(rightColor)
                            .build()
            );
        }
    }

    private void addColumnTables(Graphics2D graphics, List<Integer> healerOrders)
    {
        for (int start = 0; start < healerOrders.size(); start += BASE_MAX_HEALER_COLUMNS)
        {
            if (start > 0)
            {
                addLine("");
            }

            addColumnTable(graphics, healerOrders.subList(start, Math.min(start + BASE_MAX_HEALER_COLUMNS, healerOrders.size())));
        }
    }

    private void addColumnTable(Graphics2D graphics, List<Integer> healerOrders)
    {
        if (healerOrders.isEmpty()) return;

        List<Integer> callIndexes = getColumnCallIndexes();

        addLine(buildColumnHeader(healerOrders, graphics.getFontMetrics()), TEXT_COLOR);

        for (int callIndex : callIndexes)
        {
            addLine(buildColumnRow(healerOrders, callIndex, graphics.getFontMetrics()), TEXT_COLOR);
        }

        addLine(buildDeathTimeRow(healerOrders, graphics.getFontMetrics()), TEXT_COLOR);
    }

    private List<Integer> getColumnCallIndexes()
    {
        if (!healerController.hasActiveWaveCode(getDisplayWave()))
        {
            return List.of(-1);
        }

        return healerController.getFoodPanelCallIndexes(getDisplayWave());
    }

    private void addHealerCallRows(Graphics2D graphics, List<Integer> healerOrders)
    {
        FontMetrics metrics = graphics.getFontMetrics();

        addLine(buildHealerCallHeader(metrics), TEXT_COLOR);

        for (int healerOrder : healerOrders)
        {
            addLine(buildHealerCallRow(healerOrder, metrics), TEXT_COLOR);
        }
    }

    private String buildHealerCallHeader(FontMetrics metrics)
    {
        StringBuilder builder = new StringBuilder(padRightPixels("", scale(BASE_ROW_LABEL_WIDTH), metrics));

        for (int callIndex : healerController.getFoodPanelCallIndexes(getDisplayWave()))
        {
            builder.append(ColorUtil.prependColorTag(padCell("C" + (callIndex + 1), scale(BASE_ROW_CELL_WIDTH), metrics), TEXT_COLOR));
        }

        builder.append(ColorUtil.prependColorTag(padCell("Dead", scale(BASE_ROW_CELL_WIDTH), metrics), TEXT_COLOR));
        return builder.toString();
    }

    private String buildHealerCallRow(int healerOrder, FontMetrics metrics)
    {
        boolean spawned = healerController.hasHealerSpawned(healerOrder);
        boolean displayDead = healerController.isHealerDead(healerOrder);
        StringBuilder builder = new StringBuilder(ColorUtil.prependColorTag(
                padCell(healerController.getFoodPanelHealerLabel(getDisplayWave(), healerOrder), scale(BASE_ROW_LABEL_WIDTH), metrics),
                getHealerColor(spawned, displayDead)));

        for (int callIndex : healerController.getFoodPanelCallIndexes(getDisplayWave()))
        {
            appendFoodCell(builder, healerOrder, callIndex, scale(BASE_ROW_CELL_WIDTH), metrics);
        }

        appendDeathTimeCell(builder, healerOrder, scale(BASE_ROW_CELL_WIDTH), metrics);
        return builder.toString();
    }

    private String buildColumnHeader(List<Integer> healerOrders, FontMetrics metrics)
    {
        StringBuilder builder = new StringBuilder(padRightPixels("", scale(BASE_COLUMN_LABEL_WIDTH), metrics));

        for (int healerOrder : healerOrders)
        {
            boolean spawned = healerController.hasHealerSpawned(healerOrder);
            boolean displayDead = healerController.isHealerDead(healerOrder);
            Color color = getHealerColor(spawned, displayDead);
            String label = healerController.getFoodPanelHealerLabel(getDisplayWave(), healerOrder);

            builder.append(ColorUtil.prependColorTag(padCell(label, scale(BASE_COLUMN_CELL_WIDTH), metrics), color));
        }

        return builder.toString();
    }

    private String buildColumnRow(List<Integer> healerOrders, int callIndex, FontMetrics metrics)
    {
        String rowLabel = callIndex < 0 ? "Fed" : "C" + (callIndex + 1);
        StringBuilder builder = new StringBuilder(padCell(rowLabel, scale(BASE_COLUMN_LABEL_WIDTH), metrics));

        for (int healerOrder : healerOrders)
        {
            appendFoodCell(builder, healerOrder, callIndex, scale(BASE_COLUMN_CELL_WIDTH), metrics);
        }

        return builder.toString();
    }

    private String buildDeathTimeRow(List<Integer> healerOrders, FontMetrics metrics)
    {
        StringBuilder builder = new StringBuilder(padCell("Dead", scale(BASE_COLUMN_LABEL_WIDTH), metrics));

        for (int healerOrder : healerOrders)
        {
            appendDeathTimeCell(builder, healerOrder, scale(BASE_COLUMN_CELL_WIDTH), metrics);
        }

        return builder.toString();
    }

    private void appendFoodCell(StringBuilder builder, int healerOrder, int callIndex, int width, FontMetrics metrics)
    {
        boolean spawned = healerController.hasHealerSpawned(healerOrder);
        boolean displayDead = healerController.isHealerDead(healerOrder);
        Color color = spawned && !displayDead ? healerController.getFoodPanelTextColor(getDisplayWave(), healerOrder, callIndex) : getHealerColor(spawned, displayDead);

        if (color == null)
        {
            color = getHealerColor(spawned, displayDead);
        }

        builder.append(ColorUtil.prependColorTag(padCell(healerController.getFoodPanelText(getDisplayWave(), healerOrder, callIndex), width, metrics), color));
    }

    private void appendDeathTimeCell(StringBuilder builder, int healerOrder, int width, FontMetrics metrics)
    {
        String text = getDeathTimeText(healerOrder);
        Color color = getDeathTimeColor(healerOrder, text);

        builder.append(ColorUtil.prependColorTag(padCell(text, width, metrics), color));
    }

    private String getDeathTimeText(int healerOrder)
    {
        String deathTime = healerController.getHealerPanelDeathTime(getDisplayWave(), healerOrder);
        return deathTime == null || deathTime.isEmpty() ? "-" : deathTime;
    }

    private Color getDeathTimeColor(int healerOrder, String deathTime)
    {
        boolean spawned = healerController.hasHealerSpawned(healerOrder);
        boolean displayDead = healerController.isHealerDead(healerOrder);
        return "-".equals(deathTime) || !spawned || displayDead ? getHealerColor(spawned, displayDead) : TTK_COLOR;
    }

    private Color getHealerColor(boolean spawned, boolean dead)
    {
        return !spawned || dead ? DEAD_COLOR : TEXT_COLOR;
    }

    private String padRightPixels(String text, int width, FontMetrics metrics)
    {
        String value = text == null ? "" : text;

        if (metrics == null) return value;

        int remaining = width - metrics.stringWidth(value);

        if (remaining <= 0) return value;

        int spaceWidth = Math.max(metrics.stringWidth(" "), 1);
        return value + " ".repeat((int) Math.ceil(remaining / (double) spaceWidth));
    }

    private String padCell(String text, int width, FontMetrics metrics)
    {
        return padRightPixels(fixedWidthCellText(text), width, metrics);
    }

    private String fixedWidthCellText(String text)
    {
        String value = truncateCell(text);
        int maxCellChars = getMaxCellChars();

        if (value.length() >= maxCellChars) return value;

        return value + " ".repeat(maxCellChars - value.length());
    }

    private String truncateCell(String text)
    {
        String value = text == null ? "" : text;
        int maxCellChars = getMaxCellChars();

        if (value.length() <= maxCellChars) return value;

        return value.substring(0, maxCellChars - 3) + "...";
    }

    private void addCurrentWaveCodeAndNotes(boolean collapsible)
    {
        addCurrentWaveNotes(addCurrentWaveCode(collapsible));
    }

    private boolean addCurrentWaveCode(boolean collapsible)
    {
        String sourceText = healerController.getWaveCodeDisplaySource(getDisplayWave());

        if (isBlank(sourceText)) return false;

        if (collapsible)
        {
            codeToggleLine = LineComponent.builder()
                    .left(isCodeCollapsed() ? "Show Code" : "Hide Code")
                    .leftColor(TITLE_COLOR)
                    .build();

            panelComponent.getChildren().add(codeToggleLine);

            if (isCodeCollapsed()) return true;
        }

        for (String line : sourceText.split("\\r?\\n", -1))
        {
            addLine(line.isEmpty() ? " " : line, TEXT_COLOR);
        }

        return true;
    }

    private void addCurrentWaveCodeAndNotesIfHealer(boolean collapsible)
    {
        if (healerController.isHealerRole())
        {
            addCurrentWaveCodeAndNotes(collapsible);
        }
    }

    private void addCurrentWaveNotes(boolean separateFromCode)
    {
        String notes = getCurrentWaveNotes();

        if (isBlank(notes)) return;

        if (separateFromCode)
        {
            addLine("");
        }

        List<TimedStrategyNote> timedNotes = TimedStrategyNotes.parse(notes);
        int currentWaveTick = getCurrentWaveTick();
        int activeIndex = TimedStrategyNotes.getActiveTimedIndex(timedNotes, currentWaveTick);

        for (int i = 0; i < timedNotes.size(); i++)
        {
            TimedStrategyNote note = timedNotes.get(i);
            String line = note.getText();
            addLine(line.isEmpty() ? " " : line, TimedStrategyNotes.colorFor(note, i, activeIndex, currentWaveTick, TEXT_COLOR, DEAD_COLOR));
        }
    }

    private String getCurrentWaveNotes()
    {
		String notes = strategyManager.getActiveNotes(
				getDisplayWave(),
                getCurrentRoleContext()
        );
		return notes == null ? "" : notes.trim();
	}

	private TileMarkerRoleContext getCurrentRoleContext()
	{
		return TileMarkerRoleContext.fromRole(getDisplayRole());
	}

	private int getDisplayWave()
	{
		int waitingRoomWave = BaScrollerOverlay.getWaitingRoomWave(
				client.getLocalPlayer() == null ? null : client.getLocalPlayer().getWorldLocation());
		return waitingRoomWave > 1 ? waitingRoomWave : healerController.getCurrentWave();
	}

    private int getCurrentWaveTick()
    {
        return Math.max(0, Math.round(healerController.getCurrentWaveElapsedSeconds() / 0.6f));
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent mouseEvent)
    {
        if (codeTogglePressed || isCodeToggleClick(mouseEvent))
        {
            codeTogglePressed = false;
            mouseEvent.consume();
            return null;
        }

        return mouseEvent;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent mouseEvent)
    {
        if (isCodeToggleClick(mouseEvent))
        {
            codeTogglePressed = true;
            configManager.setConfiguration(
                    BaUtilitiesConfig.GROUP_NAME,
                    BaUtilitiesConfig.FOOD_PANEL_CODE_COLLAPSED_KEY,
                    !isCodeCollapsed()
            );
            mouseEvent.consume();
            return null;
        }

        return mouseEvent;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent mouseEvent)
    {
        if (codeTogglePressed || isCodeToggleClick(mouseEvent))
        {
            codeTogglePressed = false;
            mouseEvent.consume();
            return null;
        }

        return mouseEvent;
    }

    private boolean isCodeToggleClick(MouseEvent mouseEvent)
    {
        return mouseEvent.getButton() == MouseEvent.BUTTON1 && codeToggleBounds.contains(mouseEvent.getPoint());
    }

    private boolean isCodeCollapsed()
    {
        return config.foodPanelCodeCollapsed();
    }

    private static boolean isBlank(String value)
    {
        return value == null || value.isBlank();
    }

    @Override
    public MouseEvent mouseEntered(MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseExited(MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent mouseEvent)
    {
        return mouseEvent;
    }
}

package com.bahealerorder.common;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public final class NpcIndexOrderer
{
	public static final int NPC_INDEX_MODULUS = 1 << 16;

	private NpcIndexOrderer()
	{
	}

	public static Map<Integer, Integer> buildOrderByNpcIndex(
			Set<Integer> seenNpcIndexes,
			Map<Integer, Integer> knownOrderByNpcIndex,
			int indexBase,
			int maxOrder)
	{
		Map<Integer, Integer> orderByNpcIndex = new HashMap<>();
		Set<Integer> usedOrders = new HashSet<>();

		if (knownOrderByNpcIndex != null)
		{
			for (Map.Entry<Integer, Integer> entry : knownOrderByNpcIndex.entrySet())
			{
				Integer npcIndex = entry.getKey();
				Integer order = entry.getValue();

				if (npcIndex == null || order == null || npcIndex < 0 || order <= 0 || order > maxOrder) continue;

				orderByNpcIndex.put(npcIndex, order);
				usedOrders.add(order);
			}
		}

		if (seenNpcIndexes == null || seenNpcIndexes.isEmpty()) return orderByNpcIndex;

		List<Integer> sortedIndexes = new ArrayList<>(seenNpcIndexes);
		sortedIndexes.sort((left, right) -> Integer.compare(normalize(left, indexBase), normalize(right, indexBase)));
		int nextOrder = 1;

		for (int npcIndex : sortedIndexes)
		{
			if (orderByNpcIndex.containsKey(npcIndex)) continue;

			while (usedOrders.contains(nextOrder))
			{
				nextOrder++;
			}

			if (nextOrder > maxOrder) break;

			orderByNpcIndex.put(npcIndex, nextOrder);
			usedOrders.add(nextOrder);
			nextOrder++;
		}

		return orderByNpcIndex;
	}

	public static int normalize(int npcIndex, int indexBase)
	{
		if (indexBase < 0) return npcIndex;

		return Math.floorMod(npcIndex - indexBase, NPC_INDEX_MODULUS);
	}
}

package com.bahealerorder.common;

import com.bahealerorder.healer.HealerSharedState;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

public class BaWaveOverviewSnapshot
{
	@Getter
	private final int wave;
	private final Map<BaOverviewNpcType, Set<Integer>> spawnedOrdersByType;
	private final Map<BaOverviewNpcType, Map<Integer, Integer>> deathTicksByType;
	private final Map<BaOverviewNpcType, Map<Integer, Integer>> predictedDeathTicksByType;
	private final Map<BaOverviewNpcType, Set<Integer>> unknownTtkOrdersByType;
	@Getter
	private final String duration;

	private BaWaveOverviewSnapshot(
			int wave,
			Map<BaOverviewNpcType, Set<Integer>> spawnedOrdersByType,
			Map<BaOverviewNpcType, Map<Integer, Integer>> deathTicksByType,
			Map<BaOverviewNpcType, Map<Integer, Integer>> predictedDeathTicksByType,
			Map<BaOverviewNpcType, Set<Integer>> unknownTtkOrdersByType,
			String duration)
	{
		this.wave = wave;
		this.spawnedOrdersByType = copySets(spawnedOrdersByType);
		this.deathTicksByType = copyMaps(deathTicksByType);
		this.predictedDeathTicksByType = copyMaps(predictedDeathTicksByType);
		this.unknownTtkOrdersByType = copySets(unknownTtkOrdersByType);
		this.duration = duration;
	}

	public static BaWaveOverviewSnapshot blank(int wave)
	{
		return new BaWaveOverviewSnapshot(wave, emptySets(), emptyMaps(), emptyMaps(), emptySets(), null);
	}

	public static BaWaveOverviewSnapshot fromStates(int wave, BaWaveOverviewState waveState, HealerSharedState healerState)
	{
		Map<BaOverviewNpcType, Set<Integer>> spawnedOrdersByType = emptySets();
		Map<BaOverviewNpcType, Map<Integer, Integer>> deathTicksByType = emptyMaps();
		Map<BaOverviewNpcType, Map<Integer, Integer>> predictedDeathTicksByType = emptyMaps();
		Map<BaOverviewNpcType, Set<Integer>> unknownTtkOrdersByType = emptySets();

		for (BaOverviewNpcType type : BaOverviewNpcType.values())
		{
			int expectedCount = BaWaveInfo.getExpectedCount(wave, type);

			for (int order = 1; order <= expectedCount; order++)
			{
				if (type == BaOverviewNpcType.HEALER)
				{
					addHealerState(wave, healerState, spawnedOrdersByType, deathTicksByType, predictedDeathTicksByType, unknownTtkOrdersByType, order);
					continue;
				}

				if (waveState.hasSpawned(type, order))
				{
					spawnedOrdersByType.get(type).add(order);
				}

				Integer deathTick = waveState.getDeathTick(type, order);
				if (deathTick != null)
				{
					spawnedOrdersByType.get(type).add(order);
					deathTicksByType.get(type).put(order, deathTick);
				}
			}
		}

		return new BaWaveOverviewSnapshot(wave, spawnedOrdersByType, deathTicksByType, predictedDeathTicksByType, unknownTtkOrdersByType, null);
	}

	private static void addHealerState(
			int wave,
			HealerSharedState healerState,
			Map<BaOverviewNpcType, Set<Integer>> spawnedOrdersByType,
			Map<BaOverviewNpcType, Map<Integer, Integer>> deathTicksByType,
			Map<BaOverviewNpcType, Map<Integer, Integer>> predictedDeathTicksByType,
			Map<BaOverviewNpcType, Set<Integer>> unknownTtkOrdersByType,
			int healerOrder)
	{
		if (healerState.getWave() != wave) return;

		if (healerState.hasSpawned(healerOrder))
		{
			spawnedOrdersByType.get(BaOverviewNpcType.HEALER).add(healerOrder);
		}

		Integer actualDeathTick = healerState.getActualDeathTick(healerOrder);
		if (actualDeathTick != null)
		{
			spawnedOrdersByType.get(BaOverviewNpcType.HEALER).add(healerOrder);
			deathTicksByType.get(BaOverviewNpcType.HEALER).put(healerOrder, actualDeathTick);
			return;
		}

		Integer predictedDeathTick = healerState.getPredictedDeathTick(healerOrder);
		if (predictedDeathTick != null)
		{
			spawnedOrdersByType.get(BaOverviewNpcType.HEALER).add(healerOrder);
			predictedDeathTicksByType.get(BaOverviewNpcType.HEALER).put(healerOrder, predictedDeathTick);
		}
		else if (healerState.hasUnknownTtk(healerOrder))
		{
			spawnedOrdersByType.get(BaOverviewNpcType.HEALER).add(healerOrder);
			unknownTtkOrdersByType.get(BaOverviewNpcType.HEALER).add(healerOrder);
		}
	}

	public boolean hasSpawned(BaOverviewNpcType type, int order)
	{
		return spawnedOrdersByType.get(type).contains(order);
	}

	public Integer getDeathTick(BaOverviewNpcType type, int order)
	{
		return deathTicksByType.get(type).get(order);
	}

	public Integer getPredictedDeathTick(BaOverviewNpcType type, int order)
	{
		return predictedDeathTicksByType.get(type).get(order);
	}

	public boolean hasUnknownTtk(BaOverviewNpcType type, int order)
	{
		return unknownTtkOrdersByType.get(type).contains(order);
	}

	public BaWaveOverviewSnapshot withDuration(String duration)
	{
		return new BaWaveOverviewSnapshot(wave, spawnedOrdersByType, deathTicksByType, predictedDeathTicksByType, unknownTtkOrdersByType, duration);
	}

	public String signature()
	{
		return wave
				+ ":" + spawnedOrdersByType
				+ ":" + deathTicksByType
				+ ":" + predictedDeathTicksByType
				+ ":" + unknownTtkOrdersByType
				+ ":" + duration;
	}

	private static Map<BaOverviewNpcType, Set<Integer>> emptySets()
	{
		Map<BaOverviewNpcType, Set<Integer>> values = new EnumMap<>(BaOverviewNpcType.class);

		for (BaOverviewNpcType type : BaOverviewNpcType.values())
		{
			values.put(type, new HashSet<>());
		}

		return values;
	}

	private static Map<BaOverviewNpcType, Map<Integer, Integer>> emptyMaps()
	{
		Map<BaOverviewNpcType, Map<Integer, Integer>> values = new EnumMap<>(BaOverviewNpcType.class);

		for (BaOverviewNpcType type : BaOverviewNpcType.values())
		{
			values.put(type, new HashMap<>());
		}

		return values;
	}

	private static Map<BaOverviewNpcType, Set<Integer>> copySets(Map<BaOverviewNpcType, Set<Integer>> source)
	{
		Map<BaOverviewNpcType, Set<Integer>> copy = new EnumMap<>(BaOverviewNpcType.class);

		for (Map.Entry<BaOverviewNpcType, Set<Integer>> entry : source.entrySet())
		{
			copy.put(entry.getKey(), Collections.unmodifiableSet(new HashSet<>(entry.getValue())));
		}

		return Collections.unmodifiableMap(copy);
	}

	private static Map<BaOverviewNpcType, Map<Integer, Integer>> copyMaps(Map<BaOverviewNpcType, Map<Integer, Integer>> source)
	{
		Map<BaOverviewNpcType, Map<Integer, Integer>> copy = new EnumMap<>(BaOverviewNpcType.class);

		for (Map.Entry<BaOverviewNpcType, Map<Integer, Integer>> entry : source.entrySet())
		{
			copy.put(entry.getKey(), Collections.unmodifiableMap(new HashMap<>(entry.getValue())));
		}

		return Collections.unmodifiableMap(copy);
	}
}

